import type { MeaningPack } from '../../types';

export const taSundaraVerses4: MeaningPack = {
  lang: 'ta',
  texts: {
    'sundarakanda-40': {
      verses: {
        '0.0': 'மகாத்மாவான வாயுபுத்திரனின் சொற்களைக் கேட்டு, தேவகன்னிகை போன்ற சீதை தனக்கு நலமான சொல்லைக் கூறினாள்.',
        '0.1': '“வானரனே, இனிய செய்தி சொல்லும் உன்னைக் கண்டு, பாதி வளர்ந்த பயிருள்ள பூமி மழை பெற்றது போல் நான் மகிழ்கிறேன்.',
        '0.2': '“துயரால் மெலிந்த இந்த உறுப்புகளால் அந்த ஆண்சிங்கத்தை நான் விருப்பம் நிறைவேறித் தொடும்படி என்மேல் இரக்கம் கொண்டு செய்வாயாக.',
        '0.3': '“வானரரில் சிறந்தவனே, ராமனுக்கு இந்த அடையாளத்தையும் சொல்: காகத்தின் மீது கோபத்தால் எறிந்து அதன் ஒரு கண்ணை அழித்த தர்ப்பைப் புல்.',
        '0.4': '“‘என் திலகம் அழிந்தபோது நீ என் கன்னத்தின் ஓரத்தில் மனோசிலைத் திலகம் இட்டாய்’ — அதை நீ நிச்சயம் நினைவுகூர வேண்டும்.',
        '0.5': '“‘மகேந்திரனுக்கும் வருணனுக்கும் நிகரானவனே, வீரனான நீ கவரப்பட்டு அரக்கர் நடுவே வாழும் சீதையை எப்படிப் பொறுத்திருக்கிறாய்?’',
        '0.6': '“‘பாவமற்றவனே, இந்தத் தெய்வீகச் சூடாமணியை நான் கவனமாகக் காத்து வந்தேன்; துன்பத்தில் இதைப் பார்த்து உன்னையே பார்த்தது போல் மகிழ்ந்தேன்.’',
        '0.7': '“‘கடலில் பிறந்த இந்த ஒளிமிக்க மணியை உனக்குத் திருப்பி அனுப்புகிறேன்; இனி துயரில் ஆழ்ந்த நான் உயிர் வாழ முடியாது.’',
        '0.8': '“‘உனக்காகவே நான் தாங்க முடியாத துன்பங்களையும், இதயத்தைப் பிளக்கும் சொற்களையும், அரக்கருடன் வாழ்வதையும் பொறுத்துக்கொள்கிறேன்.’',
        '0.9': '“‘பகைவரை அழிப்பவனே, ஒரு மாதம் வரை உயிரைத் தாங்குவேன்; அரசகுமாரனே, மாதத்திற்குப் பின் நீயின்றி நான் உயிர் வாழ மாட்டேன்.’',
        '0.10': '“‘இந்த அரக்கர் அரசன் கொடியவன்; என்மேல் அவன் பார்வையும் நல்லதல்ல; நீ தாமதிக்கிறாய் என்று கேட்டால் நான் கணப்பொழுதும் உயிர் வாழ மாட்டேன்.’”',
        '0.11': 'வைதேஹி கண்ணீருடன் சொன்ன இரக்கமான சொற்களைக் கேட்டு, மிகுந்த ஒளியுடைய வாயுபுத்திரன் ஹனுமான் கூறினான்:',
        '0.12': '“தேவி, சத்தியத்தின் மேல் ஆணையிட்டுச் சொல்கிறேன்: உன் துயரால் ராமன் எல்லாவற்றிலிருந்தும் விலகியிருக்கிறான்; ராமன் துயரில் ஆழ்ந்ததால் லக்ஷ்மணனும் வருந்துகிறான்.',
        '0.13': '“எப்படியோ நீ காணப்பட்டுவிட்டாய்; இது புலம்பும் நேரமல்ல. அழகியே, விரைவில் உன் துன்பங்களின் முடிவைக் காண்பாய்.',
        '0.14': '“குற்றமற்ற அந்த இரு ஆண்சிங்க ராஜகுமாரர்களும் உன்னைக் காணும் ஊக்கத்தால் லங்கையைச் சாம்பலாக்குவார்கள்.',
        '0.15': '“அகன்ற கண்களுடையவளே, போரில் அரக்கன் ராவணனை உறவினருடன் கொன்று, அந்த இரு ராகவர்களும் உன்னை உங்கள் நகருக்கு அழைத்துச் செல்வார்கள்.',
        '0.16': '“குற்றமற்றவளே, ராமன் அறிந்துகொள்ளக்கூடிய, அவனுக்கு மேலும் மகிழ்ச்சி தரும் வேறொரு அடையாளத்தை நீ தர வேண்டும்.”',
        '0.17': 'அவள் கூறினாள்: “சிறந்த அடையாளத்தை நான் ஏற்கெனவே கொடுத்துவிட்டேன். இந்த அணிகலனைக் கவனமாகப் பார்த்து ராமனுக்கு',
        '0.18': 'வீர ஹனுமானே, உன் சொல்லில் நம்பிக்கை உண்டாகும்.” அந்தச் சிறந்த மணியை எடுத்துக்கொண்டு ஒளிமிக்க அந்த வானர சிரேஷ்டன்',
        '0.19': 'தேவியைத் தலைவணங்கி வணங்கிப் புறப்படத் தயாரானான். தாவ ஊக்கம் கொண்ட அந்த வானரப் படைத்தலைவனைக் கண்டு',
        '0.20': 'உடலைப் பெருக்கிக்கொண்டிருந்த மிகுந்த வேகமுடைய அவனிடம், கண்ணீர் நிறைந்த முகத்துடன் வாடிய ஜானகி தழுதழுத்த குரலில் கூறினாள்:',
        '0.21': '“ஹனுமானே, சிங்கம் போன்ற சகோதரர்களான ராம லக்ஷ்மணரிடமும், அமைச்சருடன் சுக்ரீவனிடமும், எல்லோரிடமும் என் சார்பில் நலம் விசாரி.',
        '0.22': '“அந்த நீண்ட கைகளுடைய ராகவன் இந்தத் துயரக் கடலிலிருந்து என்னைக் கரையேற்றும்படி நீ ஏற்பாடு செய்ய வேண்டும்.',
        '0.23': '“ராமனிடம் சென்று என் இந்தக் கடுமையான துயர வேகத்தையும், இந்த அரக்கியரின் அச்சுறுத்தல்களையும் சொல். வானர வீரனே, உன் பயணம் மங்கலமாகட்டும்.”',
        '0.24': 'இளவரசியிடமிருந்து எல்லாவற்றையும் அறிந்து, காரியம் நிறைவேறி மனம் மகிழ்ந்த அந்தக் கபி, எஞ்சிய வேலை சிறிதே என்று கண்டு, மனத்தால் வடதிசை நோக்கிச் சென்றான்.',
        '0.25': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-41': {
      verses: {
        '0.0': 'புறப்படவிருந்த அந்த வானரன் அவளால் புகழ்ச்சிச் சொற்களால் கௌரவிக்கப்பட்டு, அந்த இடத்திலிருந்து விலகிச் சென்று இவ்வாறு சிந்தித்தான்:',
        '0.1': '“இந்தக் காரியத்தில் எஞ்சியிருப்பது சிறிதே; கருவிழியாளைக் கண்டாயிற்று. முதல் மூன்று உபாயங்களைக் கடந்து, இங்கே நான்காவதே (தண்டமே) பொருந்துவதாகத் தெரிகிறது.',
        '0.2': '“அரக்கரிடம் சாமம் பயன் தராது; செல்வம் நிறைந்தவர்களிடம் தானம் பொருந்தாது; வலிமைச் செருக்குடையோரைப் பேதத்தால் வெல்ல முடியாது. ஆகவே இங்கே வீரச்செயலே எனக்கு ஏற்றதாகப் படுகிறது.',
        '0.3': '“வீரமின்றி இந்தக் காரியத்தில் எந்த முடிவும் ஏற்படாது; போரில் முக்கிய வீரர்கள் கொல்லப்பட்டால் அரக்கர்கள் இன்று எப்படியோ மென்மையடையக்கூடும்.',
        '0.4': '“முக்கியக் காரியம் முடிந்தபின், முதல் காரியத்திற்கு இடையூறின்றி மேலும் பல காரியங்களைச் சாதிப்பவனே காரியம் செய்யத் தகுந்தவன்.',
        '0.5': '“சிறிய செயலுக்கும் ஒரே சாதனம் போதாது; நோக்கத்தைப் பல வகையில் அறிந்தவனே அதைச் சாதிக்க வல்லவன்.',
        '0.6': '“இங்கேயே பகைவரின் வலிமைக்கும் நம் வலிமைக்கும் உள்ள வேறுபாட்டைத் தெளிவாக அறிந்து, உறுதியுடன் இன்று வானர அரசனிடம் சென்றால், என் தலைவனின் கட்டளை முழுமையாக நிறைவேறும்.',
        '0.7': '“இன்று அரக்கருடன் எனக்குப் போர் எளிதில் எப்படி நேரும்? பத்துத்தலையன் தன் வலிமையான படையைப் போரில் என் முன் எப்படிக் கொண்டுவருவான்?',
        '0.8': '“அப்போது போரில் அமைச்சர்கள், படை, பின்செல்வோருடன் பத்துத்தலையனை எதிர்கொண்டு, அவன் மனத்தின் எண்ணத்தையும் வலிமையையும் எளிதில் அறிந்து இங்கிருந்து திரும்புவேன்.',
        '0.9': '“இந்தக் கொடியவனின் இந்தச் சோலை நந்தனவனம் போல் சிறந்தது, கண்ணுக்கும் மனத்துக்கும் இனியது, பலவகை மரங்களும் கொடிகளும் நிறைந்தது.',
        '0.10': '“காய்ந்த காட்டை நெருப்பு அழிப்பது போல் இதை அழிப்பேன்; இது அழிந்தால் அந்த ராவணன் கோபம் கொள்வான்.',
        '0.11': '“அப்போது அரக்கர் தலைவன் குதிரைகள், பெருந்தேர்கள், யானைகளுடன், சூலம், இரும்புத் தண்டு, பட்டிசம் ஏந்திய பெரும் படையை அனுப்புவான்; அப்போது பெரும் போர் நடக்கும்.',
        '0.12': '“தடையற்ற வீரமுடைய நான் அந்தக் கடும் வீரமுடைய அரக்கர்களைப் போரில் எதிர்கொண்டு, ராவணன் அனுப்பிய அந்தப் படையை அழித்து, மகிழ்ச்சியுடன் வானர அரசனிடம் செல்வேன்.”',
        '0.13': 'அப்போது கடும் வீரமுடைய மாருதி காற்றைப் போல் சினந்து, தன் தொடைகளின் பெரும் வேகத்தால் மரங்களை வீசி எறியத் தொடங்கினான்.',
        '0.14': 'அப்போது வீர ஹனுமான் மதங்கொண்ட பறவைகளின் ஒலியால் எதிரொலித்த, பலவகை மரங்களும் கொடிகளும் நிறைந்த அந்தப் பிரமதாவனத்தை அழித்தான்.',
        '0.15': 'பிடுங்கப்பட்ட மரங்களாலும், உடைந்த குளங்களாலும், தூளான குன்றுச் சிகரங்களாலும் அந்தச் சோலை காண்பதற்கு விகாரமாயிற்று.',
        '0.16': 'பலவகைப் பறவைகளின் அலறலாலும், உடைந்த நீர்நிலைகளாலும், வாடிய செந்நிறத் தளிர்களாலும், வாடிய மரம் கொடிகளாலும் நிறைந்து,',
        '0.17': 'அந்தச் சோலை காட்டுத்தீயால் தாக்கப்பட்டது போல் ஒளியிழந்தது; ஆடை கலைந்த கலங்கிய பெண்களைப் போல் அந்தக் கொடிகள் தோன்றின.',
        '0.18': 'கொடிவீடுகளும் ஓவியமாடங்களும் அழிந்து, கொடிய விலங்குகள், மான்கள், பறவைகள் அலறி, கல்வீடுகளும் பிற கட்டடங்களும் தகர்ந்து, அந்தப் பெரும் சோலை தன் அழகையே இழந்தது.',
        '0.19': 'பத்துத்தலையனின் அந்தப் பிரமதாவனத்தின் நிலம், நடுங்கும் அசோகக் கொடிகள் படர்ந்திருந்தது, குரங்கின் வலிமையால் சோகக் கொடிகள் படர்ந்த நிலமாயிற்று.',
        '0.20': 'இவ்வாறு வலிமைமிக்க அந்த மன்னனின் மனத்துக்குப் பெரும் வேதனையை உண்டாக்கி, தனியாகப் பல வலியவர்களுடன் போரிட விரும்பி, ஒளியால் சுடர்விட்ட அந்த மகாகபி தோரணத்தின் மீது நின்றான்.',
        '0.21': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்தொன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-42': {
      verses: {
        '0.0': 'அப்போது பறவைகளின் கூச்சலாலும் மரங்கள் முறியும் ஓசையாலும் லங்கைவாசிகள் அனைவரும் அச்சத்தால் கலங்கினர்.',
        '0.1': 'விலங்குகளும் பறவைகளும் அஞ்சி ஓடிக் கதறின; அரக்கர்களுக்குக் கொடிய அபசகுனங்கள் தோன்றின.',
        '0.2': 'அப்போது உறக்கம் கலைந்த விகார முகமுடைய அரக்கியர் அழிந்த அந்தச் சோலையையும் அந்த வீர மகாகபியையும் கண்டனர்.',
        '0.3': 'அவர்களைக் கண்டு, நீண்ட கைகளும் பெரும் உறுதியும் வலிமையும் உடைய அவன் அரக்கியருக்கு அச்சமூட்டும் பேருருவம் எடுத்தான்.',
        '0.4': 'அப்போது மலைபோன்ற பெரிய உடலுடைய வலிய வானரனைக் கண்டு அரக்கியர் ஜானகியிடம் கேட்டனர்:',
        '0.5': '“இவன் யார்? யாருடையவன்? எங்கிருந்து, எதற்காக இங்கே வந்தான்? உன்னுடன் இவன் எப்படிப் பேசினான்?',
        '0.6': '“அகன்ற கண்ணாளே, எங்களுக்குச் சொல்; பாக்கியவதியே, அஞ்சாதே. கருங்கடைக்கண்ணாளே, இவன் உன்னுடன் என்ன பேசினான்?”',
        '0.7': 'அப்போது எல்லா உறுப்புகளிலும் அழகிய கற்புடைய சீதை கூறினாள்: “விரும்பிய உருவெடுக்கும் அரக்கர்களை அறிவதற்கு எனக்கு என்ன வழி?',
        '0.8': '“இவன் யார், என்ன செய்வான் என்பதை நீங்களே அறிவீர்கள்; பாம்பின் கால்களைப் பாம்பே அறியும், ஐயமில்லை.',
        '0.9': '“நானும் மிகவும் அஞ்சியிருக்கிறேன்; இவன் யாரென்று எனக்குத் தெரியாது. விரும்பிய உருவில் வந்த அரக்கன் என்றே எண்ணுகிறேன்.”',
        '0.10': 'வைதேஹியின் சொல்லைக் கேட்டு அரக்கியர் விரைந்து சிதறினர்; சிலர் அங்கேயே நின்றனர், சிலர் ராவணனிடம் தெரிவிக்கச் சென்றனர்.',
        '0.11': 'ராவணனிடம் சென்ற விகார முகமுடைய அரக்கியர் விகாரமான பயங்கர வானரனைப் பற்றி அவனுக்குத் தெரிவித்தனர்:',
        '0.12': '“அரசே, அசோகவனத்தின் நடுவில் பயங்கர உடலும் அளவற்ற வீரமும் உடைய ஒரு குரங்கு சீதையுடன் பேசிவிட்டு நிற்கிறது.',
        '0.13': '“மான்விழியாளான ஜானகி சீதையிடம் நாங்கள் பலவாறு கேட்டும், அந்தக் குரங்கைப் பற்றிச் சொல்ல அவள் விரும்பவில்லை.',
        '0.14': '“அவன் இந்திரனின் தூதனாகவோ, குபேரனின் தூதனாகவோ, அல்லது சீதையைத் தேடும் விருப்பத்தால் ராமன் அனுப்பியவனாகவோ இருக்கலாம்.',
        '0.15': '“அற்புத உருவுடைய அவனே, பலவகை விலங்குக் கூட்டங்கள் நிறைந்த உன் அழகிய பிரமதாவனத்தை அழித்துவிட்டான்.',
        '0.16': '“அவன் அழிக்காத பகுதி எதுவும் அங்கே இல்லை; ஜானகி தேவி இருக்கும் இடத்தை மட்டும் அவன் அழிக்கவில்லை.',
        '0.17': '“ஜானகியைக் காக்கவோ களைப்பாலோ என்று தெரியவில்லை; அவனுக்கு என்ன களைப்பு? அவளையே அவன் காத்திருக்கிறான்.',
        '0.18': '“சீதை தானே தங்கியிருக்கும், அழகிய தளிர்களும் இலைகளும் நிறைந்த அந்த உயர்ந்த சிம்சுபா மரத்தையும் அவன் காத்திருக்கிறான்.',
        '0.19': '“சீதையுடன் பேசி வனத்தை அழித்த அந்தக் கொடிய உருவனுக்கு நீ கடும் தண்டனை விதிக்க வேண்டும்.',
        '0.20': '“அரக்கர் கணங்களின் தலைவனே, நீ மனத்தில் ஏற்றுக்கொண்ட சீதையுடன், உயிரை விட்டவனன்றி வேறு யார் பேசுவான்?”',
        '0.21': 'அரக்கியரின் சொற்களைக் கேட்டு அரக்கர் தலைவன் ராவணன் கோபத்தால் கண்களைச் சுழற்றி, சிதைநெருப்பைப் போல் கொழுந்துவிட்டெரிந்தான்.',
        '0.22': 'சினந்த அவனுடைய கண்களிலிருந்து, எரியும் இரு விளக்குகளிலிருந்து சுடருடன் எண்ணெய்த் துளிகள் விழுவது போல் கண்ணீர்த் துளிகள் விழுந்தன.',
        '0.23': 'மிகுந்த ஒளியுடைய அவன் தனக்கு நிகரான கிங்கரர் எனும் வீர அரக்கர்களுக்கு ஹனுமானைப் பிடிக்கக் கட்டளையிட்டான்.',
        '0.24': 'வேகமுடைய அந்தக் கிங்கரர்களில் எண்பதாயிரம் பேர் கைகளில் கூடங்களும் முத்கரங்களும் ஏந்தி அந்த மாளிகையிலிருந்து புறப்பட்டனர்.',
        '0.25': 'பெருவயிறும் பெருங்கோரைப்பற்களும் உடைய, பயங்கர உருவமும் பெரும் வலிமையும் கொண்ட அவர்கள் அனைவரும் போர் விருப்புடன் ஹனுமானைப் பிடிக்கத் துடித்தனர்.',
        '0.26': 'தோரணத்தின் மேல் நின்ற அந்தக் கபியை நெருங்கி, அவர்கள் பெரும் வேகத்துடன் நெருப்பில் விழும் விட்டில்களைப் போல் அவன் மீது பாய்ந்தனர்.',
        '0.27': 'அவர்கள் விசித்திரமான கதைகளாலும், பொற்பட்டை பூண்ட பரிகங்களாலும், சூரியன் போல் ஒளிரும் அம்புகளாலும் வானர சிரேஷ்டனைத் தாக்கினர்.',
        '0.28': 'முத்கரம், பட்டிசம், சூலம், பிராசம், தோமரம் ஆகியவற்றைக் கைகளில் ஏந்தி, அவர்கள் திடீரென ஹனுமானைச் சூழ்ந்து முன்னே நின்றனர்.',
        '0.29': 'ஒளியும் பொலிவும் உடைய, மலைபோன்ற ஹனுமானும் வாலைத் தரையில் அறைந்து பெருமுழக்கமிட்டான்.',
        '0.30': 'பேருடல் எடுத்து, வாயுபுத்திரன் ஹனுமான் லங்கையை ஒலியால் நிரப்பியபடி வாலை அறைந்தான்.',
        '0.31': 'அந்த அறைதலின் எதிரொலிக்கும் பேரொலியால் வானிலிருந்து பறவைகள் விழுந்தன; அவன் உரக்க இவ்வாறு முழங்கினான்:',
        '0.32': '“மிகுந்த வலிமையுடைய ராமனுக்கு வெற்றி! பெருவலியனான லக்ஷ்மணனுக்கு வெற்றி! ராகவனால் காக்கப்படும் அரசன் சுக்ரீவனுக்கு வெற்றி!',
        '0.33': '“எளிதில் செயல்களைச் சாதிக்கும் கோசல மன்னன் ராமனின் அடியவன் நான் — பகைப்படைகளை அழிக்கும் வாயுபுத்திரன் ஹனுமான்.',
        '0.34': '“ஆயிரக்கணக்கான பாறைகளாலும் மரங்களாலும் தாக்கும் எனக்குப் போரில் ஆயிரம் ராவணர்களும் ஈடாக மாட்டார்கள்.',
        '0.35': '“லங்கை நகரை அழித்து, மைதிலியை வணங்கி, அரக்கர் அனைவரும் பார்த்திருக்கவே காரியம் நிறைவேறியவனாகச் செல்வேன்.”',
        '0.36': 'அவனுடைய முழக்கத்தின் ஒலியால் அவர்கள் அச்சமுற்றனர்; அந்தி மேகம் போல் உயர்ந்து நின்ற ஹனுமானைக் கண்டனர்.',
        '0.37': 'அப்போது தலைவனின் கட்டளையால் அச்சம் நீங்கிய அந்த அரக்கர்கள் விசித்திரமான கொடிய ஆயுதங்களுடன் எல்லாப் பக்கங்களிலிருந்தும் கபியின் மீது பாய்ந்தனர்.',
        '0.38': 'அந்த வீரர்களால் எல்லாப் பக்கமும் சூழப்பட்ட அந்த மகாபலன், தோரணத்தில் சார்த்தியிருந்த பயங்கரமான இரும்புப் பரிகத்தைப் பற்றினான்.',
        '0.39': 'வினதையின் மகன் கருடன் துடிக்கும் பாம்பைப் பற்றுவது போல், அந்தப் பரிகத்தை எடுத்து அவன் இரவில் திரிவோரை அடித்து வீழ்த்தினான்.',
        '0.40': 'அதை ஏந்தி வீர மாருதி வானில் உலவி, ஆயிரம் கண்ணுடைய இந்திரன் வஜ்ராயுதத்தால் தைத்தியர்களைக் கொன்றது போல் அவர்களை அழித்தான்.',
        '0.41': 'கிங்கர அரக்கர்களைக் கொன்று, மேலும் போரை விரும்பிய அந்த மகாவீரனான வாயுபுத்திரன் மீண்டும் தோரணத்தின் மேல் நின்றான்.',
        '0.42': 'அப்போது அந்த அச்சத்திலிருந்து தப்பிய சில அரக்கர்கள் கிங்கரர் அனைவரும் கொல்லப்பட்டதை ராவணனிடம் தெரிவித்தனர்.',
        '0.43': 'அரக்கர்களின் பெரும் படை கொல்லப்பட்டதைக் கேட்டு, சினத்தால் கண்களைச் சுழற்றிய அரசன், வீரத்தில் நிகரற்றவனும் போரில் வெல்லுதற்கரியவனுமான பிரஹஸ்தனின் மகனுக்குக் கட்டளையிட்டான்.',
        '0.44': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்திரண்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-43': {
      verses: {
        '0.0': 'கிங்கரர்களைக் கொன்ற பின் ஹனுமான் சிந்தித்தான்: “நான் சோலையை அழித்தேன், ஆனால் சைத்தியப் பிராசாதத்தை அழிக்கவில்லை.',
        '0.1': '“ஆகவே இன்றே இந்த மாளிகையை அழிப்பேன்.” என்று எண்ணி, ஹனுமான் தன் வலிமையைக் காட்டியவாறு,',
        '0.2': 'வானர சிரேஷ்டனான வாயுபுத்திரன் ஹனுமான் தாவி, மேரு சிகரம் போல் உயர்ந்த அந்தச் சைத்தியப் பிராசாதத்தின் மேல் ஏறினான்.',
        '0.3': 'மலைபோன்ற அந்த மாளிகையில் ஏறிய மிகுந்த ஒளியுடைய வானரப் படைத்தலைவன், உதித்த மற்றொரு சூரியனைப் போல் விளங்கினான்.',
        '0.4': 'உயர்ந்த சைத்தியப் பிராசாதத்தைக் கைப்பற்றிய வெல்லமுடியாத ஹனுமான், ஒளியால் சுடர்விட்டு பாரியாத்ர மலை போல் தோன்றினான்.',
        '0.5': 'பேருருவெடுத்த வல்லமையுடைய வாயுபுத்திரன் துணிவுடன் தோள்களைத் தட்டி லங்கையை ஒலியால் நிரப்பினான்.',
        '0.6': 'காதுகளைத் தாக்கும் அந்தப் பேரொலியால் அங்கே பறவைகள் விழுந்தன; சைத்தியக் காவலர்கள் மயங்கினர்.',
        '0.7': '“அஸ்திரங்களை அறிந்த ராமனுக்கு வெற்றி! பெருவலியனான லக்ஷ்மணனுக்கு வெற்றி! ராகவனால் காக்கப்படும் அரசன் சுக்ரீவனுக்கு வெற்றி!',
        '0.8': '“எளிதில் செயல்களைச் சாதிக்கும் கோசல மன்னன் ராமனின் அடியவன் நான் — பகைப்படைகளை அழிக்கும் வாயுபுத்திரன் ஹனுமான்.',
        '0.9': '“ஆயிரக்கணக்கான பாறைகளாலும் மரங்களாலும் தாக்கும் எனக்குப் போரில் ஆயிரம் ராவணர்களும் ஈடாக மாட்டார்கள்.',
        '0.10': '“லங்கை நகரை அடக்கி, மைதிலியை வணங்கி, அரக்கர் அனைவரும் பார்த்திருக்கவே காரியம் நிறைவேறியவனாகச் செல்வேன்.”',
        '0.11': 'இவ்வாறு கூறி, சைத்தியத்தின் மேல் நின்ற பேருருவ வானரத் தலைவன் அரக்கர்களுக்கு அச்சமூட்டியவாறு பயங்கரமாக முழங்கினான்.',
        '0.12': 'அந்தப் பெருமுழக்கத்தால் நூறு சைத்தியக் காவலர்கள் பிராசம், வாள், கோடரி முதலிய பலவித ஆயுதங்களுடன் வந்தனர்.',
        '0.13': 'அவற்றை வீசியவாறு அந்தப் பேருருவ அரக்கர்கள் மாருதியைச் சூழ்ந்தனர்; விசித்திரக் கதைகளாலும் பொற்பட்டைப் பரிகங்களாலும்',
        '0.14': 'சூரியன் போல் ஒளிரும் அம்புகளாலும் அவர்கள் வானர சிரேஷ்டனைத் தாக்கினர். கங்கை நீரின் பரந்த பெரும் சுழல் போல்,',
        '0.15': 'வானர சிரேஷ்டனைச் சூழ்ந்த அந்த அரக்கர் கூட்டம் விளங்கியது. அப்போது வாயுபுத்திரன் சினந்து பயங்கர உருவம் எடுத்தான்.',
        '0.16': 'வாயுபுத்திரன் ஹனுமான் அந்த மாளிகையின் பொன்னால் அலங்கரிக்கப்பட்ட பெரிய தூணை வேகமாகப் பிடுங்கி,',
        '0.17': 'அந்த மகாபலன் நூறு விளிம்புகளுடைய அதைச் சுழற்றினான்; அங்கே நெருப்புண்டாகி மாளிகையும் எரியத் தொடங்கியது.',
        '0.18': 'மாளிகை எரிவதைக் கண்டு, அந்த வானரத் தலைவன், இந்திரன் வஜ்ராயுதத்தால் அசுரர்களைக் கொல்வது போல், அந்த நூறு அரக்கர்களையும் கொன்று,',
        '0.19': 'அந்தப் பொலிவுடையவன் வானில் நின்று இந்தச் சொல்லைக் கூறினான்: “என்னைப் போன்ற ஆயிரக்கணக்கான மகாத்மாக்கள் அனுப்பப்பட்டுள்ளனர் —',
        '0.20': '“சுக்ரீவனின் ஆணைக்குக் கட்டுப்பட்ட வலிய வானரத் தலைவர்கள். நாங்களும் மற்ற வானரர்களும் பூமி முழுவதும் திரிகிறோம்.',
        '0.21': '“சிலர் பத்து யானைகளின் வலிமையுடையவர், சிலர் அதைவிடப் பத்து மடங்கு; சிலர் ஆயிரம் யானைகளுக்கு நிகரான வீரமுடையவர்.',
        '0.22': '“சிலர் வெள்ளப்பெருக்கின் வலிமையுடையவர், சிலர் காற்றின் வலிமைக்கு நிகரானவர்; அந்த வானரத் தலைவர்களில் சிலர் அளவற்ற வலிமையுடையவர்.',
        '0.23': '“பற்களையும் நகங்களையுமே ஆயுதமாகக் கொண்ட இத்தகைய நூற்றுக்கணக்கான, லட்சக்கணக்கான, பல்லாயிரக்கணக்கான, கோடிக்கணக்கான வானரர்களால் சூழப்பட்டு,',
        '0.24': '“உங்கள் அனைவரையும் அழிப்பவனான சுக்ரீவன் வருவான். மகாத்மாவான இக்ஷ்வாகு வீரனுடன் பகை கொண்டதால், இந்த லங்கை நகரமும் இருக்காது, நீங்களும் இருக்க மாட்டீர்கள், ராவணனும் இருக்க மாட்டான்.”',
        '0.25': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்துமூன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-44': {
      verses: {
        '0.0': 'அரக்கர் தலைவனின் கட்டளைப்படி பிரஹஸ்தனின் வலிய மகனான, பெருங்கோரைப்பற்களுடைய ஜம்புமாலி வில்லேந்திப் புறப்பட்டான்.',
        '0.1': 'அவன் சிவப்பு மாலையும் சிவப்பு ஆடையும் அணிந்து, ஆரமும் அழகிய குண்டலங்களும் பூண்டிருந்தான்; பேருருவமும் சுழலும் கண்களும் கொண்ட, கொடிய, போரில் வெல்லுதற்கரியவன்.',
        '0.2': 'இந்திரவில் போன்ற, அழகிய அம்புகளுடைய தன் பெரிய வில்லை இடிபோன்ற ஓசையுடன் வேகமாக நாணொலி எழுப்பினான்.',
        '0.3': 'அந்த வில்லின் பெரும் நாணொலியால் திசைகளும் இடைத்திசைகளும் வானமும் திடீரென நிறைந்தன.',
        '0.4': 'கழுதைகள் பூட்டிய தேரில் வந்த அவனைக் கண்டு, வேகமுடைய ஹனுமான் மகிழ்ந்து முழங்கினான்.',
        '0.5': 'தோரணத்தின் உச்சியில் இருந்த மகாகபி ஹனுமானை நீண்ட கைகளுடைய ஜம்புமாலி கூர்மையான அம்புகளால் துளைத்தான்.',
        '0.6': 'அந்தக் கபீஸ்வரனின் முகத்தில் அர்த்தசந்திர அம்பாலும், தலையில் ஒரு கர்ணி அம்பாலும், புயங்களில் பத்து நாராசங்களாலும் தாக்கினான்.',
        '0.7': 'அம்பால் தாக்கப்பட்ட அவனுடைய செம்பு நிற முகம், கூதிர்காலத்தில் சூரியக் கதிர் பட்ட மலர்ந்த தாமரை போல் விளங்கியது.',
        '0.8': 'இரத்தத்தால் மேலும் சிவந்த அவனுடைய அந்தச் சிவந்த முகம், வானில் சந்தனத் துளிகள் தெளிக்கப்பட்ட பெரிய தாமரை போல் விளங்கியது.',
        '0.9': 'அரக்கனின் அம்புகளால் தாக்கப்பட்ட மகாகபி சினந்தான்; அப்போது அருகில் இருந்த மிகப் பெரிய பாறையைக் கண்டான்.',
        '0.10': 'அந்த வலியவன் அதை விரைவாகப் பெயர்த்து வலுவாக எறிந்தான்; சினந்த அரக்கன் பத்து அம்புகளால் அதைத் தகர்த்தான்.',
        '0.11': 'அந்த முயற்சி வீணானதைக் கண்டு, கடும் வீரமுடைய வலிய ஹனுமான் ஒரு பெரிய சால மரத்தைப் பிடுங்கிச் சுழற்றினான்.',
        '0.12': 'சால மரத்தைச் சுழற்றும் வலிமைமிக்க கபியைக் கண்டு, பெருவலியனான ஜம்புமாலி மிகப் பல அம்புகளை எய்தான்.',
        '0.13': 'நான்கு அம்புகளால் சால மரத்தை வெட்டினான்; வானரனின் புயத்தில் ஐந்து, தலையில் ஒன்று, மார்பில் பத்து அம்புகளால் தாக்கினான்.',
        '0.14': 'அம்புகளால் நிறைந்த உடலுடன் பெருஞ்சினம் கொண்ட அவன், அதே பரிகத்தைப் பற்றி வேகமாகச் சுழற்றினான்.',
        '0.15': 'மிகுந்த வேகமும் வலிமையும் உடைய அவன் அதை அதிவேகமாகச் சுழற்றி ஜம்புமாலியின் அகன்ற மார்பின் மேல் வீழ்த்தினான்.',
        '0.16': 'அவனுடைய தலையோ, கைகளோ, முழங்கால்களோ இல்லை; வில், தேர், குதிரைகள், அம்புகள் எதுவும் அங்கே காணப்படவில்லை.',
        '0.17': 'அவனால் வேகமாகத் தாக்கப்பட்ட பெருவலியனான ஜம்புமாலி உறுப்புகளும் அணிகலன்களும் நொறுங்கி இறந்து தரையில் விழுந்தான்.',
        '0.18': 'ஜம்புமாலியும் வலிமைமிக்க கிங்கரர்களும் கொல்லப்பட்டதைக் கேட்டு ராவணன் சினத்தால் சிவந்த கண்களுடன் கோபம் கொண்டான்.',
        '0.19': 'வலிய பிரஹஸ்தனின் மகன் கொல்லப்பட்டதும், சினத்தால் செந்நிறக் கண்களைச் சுழற்றிய இரவுலாவிகளின் தலைவன், மிகுந்த வீரமும் ஆற்றலும் உடைய அமைச்சர்களின் மகன்களுக்கு உடனே கட்டளையிட்டான்.',
        '0.20': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்துநான்காம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-45': {
      verses: {
        '0.0': 'அப்போது அரக்கர் தலைவனால் தூண்டப்பட்ட, நெருப்பைப் போல் ஒளிரும் ஏழு அமைச்சர் மகன்கள் அந்த மாளிகையிலிருந்து புறப்பட்டனர்.',
        '0.1': 'பெரும் படை சூழ்ந்த, வில்லேந்திய, பெருவலிமையுடைய, அஸ்திர வித்தையில் தேர்ந்தவர்களில் சிறந்த, ஒருவரை ஒருவர் விஞ்சி வெல்ல விரும்பிய அவர்கள்,',
        '0.2': 'பொன்வலைகளால் அலங்கரிக்கப்பட்ட, கொடிகளும் பதாகைகளும் உடைய, மேகமுழக்கம் போல் ஒலிக்கும், குதிரைகள் பூட்டிய பெருந்தேர்களில் வந்தனர்;',
        '0.3': 'அளவற்ற வீரமுடைய அவர்கள் மகிழ்ச்சியுடன் புடம்போட்ட பொன்னால் அலங்கரிக்கப்பட்ட விற்களை நாணொலித்து, மின்னலுடைய மேகங்களைப் போல் தோன்றினர்.',
        '0.4': 'கிங்கரர்கள் கொல்லப்பட்டதை அறிந்த அவர்களின் தாய்மார்கள் உறவினர் நண்பர்களுடன் துயரத்தால் கலங்கினர்.',
        '0.5': 'ஒருவருக்கொருவர் போட்டியிட்டு, புடம்போட்ட பொன் அணிகலன்கள் பூண்ட அவர்கள் தோரணத்தின் மேல் நின்ற ஹனுமான் மீது பாய்ந்தனர்.',
        '0.6': 'அம்பு மழை பொழிந்து, தேர்களின் இடிமுழக்கம் போன்ற ஒலியுடன், அந்த அரக்க மேகங்கள் மழைக்கால மேகங்களைப் போல் திரிந்தன.',
        '0.7': 'அந்த அம்பு மழைகளால் மூடப்பட்ட ஹனுமானின் உருவம், மழையால் மூடப்பட்ட மலையரசன் போல் மறைந்தது.',
        '0.8': 'விரைந்து செல்லும் அந்தக் கபி தெளிந்த வானில் உலவியபடி அவர்களின் அம்புகளையும் வீரர்களின் தேர் வேகங்களையும் தவிர்த்தான்.',
        '0.9': 'அந்த வில்வீரர்களுடன் வானில் விளையாடிய அந்த வீரன், வானவில்லுடைய மேகங்களுடன் வானில் விளையாடும் வல்லமையுள்ள காற்றைப் போல் விளங்கினான்.',
        '0.10': 'பயங்கரமாக முழங்கி அந்தப் பெரும் படையை அச்சுறுத்தியவாறு, வலிய ஹனுமான் அந்த அரக்கர்கள் மீது வேகமாகப் பாய்ந்தான்.',
        '0.11': 'பகைவரை வாட்டும் அவன் சிலரை உள்ளங்கையாலும், சிலரைக் கால்களாலும் அடித்தான்; சிலரை முஷ்டிகளால் குத்தி, சிலரை நகங்களால் கிழித்தான்.',
        '0.12': 'சிலரை மார்பாலும், வேறு சிலரைத் தொடைகளாலும் நசுக்கினான்; சிலர் அவனுடைய முழக்கத்தாலேயே அங்கேயே தரையில் விழுந்தனர்.',
        '0.13': 'அவர்கள் இறந்து தரையில் விழுந்தபோது, அவர்களுடைய படை முழுவதும் அச்சத்தால் பத்துத் திசைகளிலும் ஓடியது.',
        '0.14': 'யானைகள் கர்ண கடூரமாகப் பிளிறின, குதிரைகள் தரையில் விழுந்தன; இருக்கைகளும் கொடிகளும் குடைகளும் உடைந்த தேர்களால் நிலம் நிறைந்தது.',
        '0.15': 'வழியில் பாயும் இரத்த ஆறுகள் காணப்பட்டன; அப்போது லங்கை பலவித ஓலங்களால் விகாரமாக எதிரொலித்தது.',
        '0.16': 'செருக்குடன் பெருகிய அந்த அரக்கர்களைக் கொன்று, கடும் வீரமுடைய அந்த வலிய வீரக்கபி மேலும் பிற அரக்கர்களுடன் போரிட விரும்பி மீண்டும் அதே தோரணத்தை அடைந்தான்.',
        '0.17': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்தைந்தாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-46': {
      verses: {
        '0.0': 'மகாத்மாவான வானரனால் அமைச்சர் மகன்கள் கொல்லப்பட்டதை அறிந்து, ராவணன் தன் உணர்வை மறைத்துக்கொண்டு ஒரு சிறந்த முடிவுக்கு வந்தான்.',
        '0.1': 'விரூபாக்ஷன், யூபாக்ஷன், அரக்கன் துர்தரன், பிரகசன், பாசகர்ணன் — இந்த ஐந்து படைத்தலைவர்களுக்கும்,',
        '0.2': 'நீதியில் தேர்ந்த, ஹனுமானைப் பிடிப்பதில் கலக்கமற்ற, போரில் காற்றின் வேகத்துக்கு நிகரான அந்த வீரர்களுக்குப் பத்துக்கழுத்தன் கட்டளையிட்டான்:',
        '0.3': '“படைத்தலைவர்களே, நீங்கள் அனைவரும் பெரும் படையுடன், குதிரைகள், தேர்கள், யானைகளுடன் சென்று அந்தக் கபியைத் தண்டியுங்கள்.',
        '0.4': '“அந்தக் காட்டுவாசியை நெருங்கும்போது நீங்கள் எச்சரிக்கையாக இருக்க வேண்டும்; இடத்துக்கும் காலத்துக்கும் ஏற்றபடி செயல்பட வேண்டும்.',
        '0.5': '“அவனுடைய செயல்களைக் கொண்டு ஆராய்ந்தால் அவனை வெறும் கபி என்று நான் எண்ணவில்லை; எல்லா வகையிலும் அவன் பெரும் வலிமையுடைய ஒரு மாபெரும் உயிர்.',
        '0.6': '“‘இவன் வானரன்’ என்று எண்ணினால் என் மனம் தெளிவடையவில்லை; நடந்ததைப் பார்க்கும்போது அவனைக் கபி என்று நான் எண்ணவில்லை.',
        '0.7': '“ஒருவேளை தவவலிமையால் நமக்காக இந்திரன் இவனைப் படைத்திருக்கலாம். நாகர், யக்ஷர், கந்தர்வர், தேவர், அசுரர், மகரிஷிகள்',
        '0.8': '“என்னுடன் அனுப்பப்பட்ட உங்கள் அனைவராலும் வெல்லப்பட்டுள்ளனர்; அவர்கள் நமக்கு ஏதாவது தீங்கு நிச்சயம் செய்ய முயல்வார்கள்.',
        '0.9': '“ஆகவே ஐயமில்லை, அவனைப் பலவந்தமாகப் பிடியுங்கள். படைத்தலைவர்களே, நீங்கள் அனைவரும் பெரும் படையுடன் சென்று,',
        '0.10': '“குதிரைகள், தேர்கள், யானைகளுடன் அந்தக் கபியைத் தண்டியுங்கள். உறுதியான வீரமுடைய அந்தக் கபியை நீங்கள் இகழக் கூடாது.',
        '0.11': '“முன்பு நான் பெரும் வீரமுடைய வானரர்களைக் கண்டிருக்கிறேன் — வாலி, சுக்ரீவன், வலிமைமிக்க ஜாம்பவான்,',
        '0.12': '“படைத்தலைவன் நீலன், துவிவிதன் முதலிய பிறர்; ஆனால் அவர்களில் எவருக்கும் இத்தகைய பயங்கர வேகமோ, ஒளியோ, வீரமோ இல்லை,',
        '0.13': '“இத்தகைய அறிவோ, வலிமையும் ஊக்கமோ, உருமாற்றும் ஆற்றலோ இல்லை. இது குரங்கு உருவில் நிற்கும் ஒரு மாபெரும் உயிர் என்று அறியுங்கள்.',
        '0.14': '“பெரும் முயற்சியுடன் அவனை அடக்குங்கள். இந்திரனுடனும் தேவர், அசுரர், மனிதருடனும் கூடிய மூவுலகங்களும்',
        '0.15': '“போர்க்களத்தில் உங்கள் முன் நிற்கப் போதாது; இருந்தாலும் நீதியறிந்தவன் போரில் வெற்றியை விரும்பும்போது',
        '0.16': '“கவனமாகத் தன்னைக் காத்துக்கொள்ள வேண்டும், ஏனெனில் போரில் வெற்றி நிலையற்றது.” பெரும் ஆற்றலுடைய அவர்கள் அனைவரும் தலைவனின் சொல்லை ஏற்று,',
        '0.17': 'பெரும் வேகத்துடன், நெருப்பைப் போல் ஒளியுடன், தேர்கள், மதயானைகள், மிக வேகமான குதிரைகளுடன் புறப்பட்டனர்,',
        '0.18': 'பலவகைக் கூர்மையான ஆயுதங்களுடனும் முழுப் படையுடனும். அப்போது அந்த வீரர்கள் ஒளிர்ந்துகொண்டிருந்த மகாகபியைக் கண்டனர் —',
        '0.19': 'உதிக்கும் சூரியன் போல் தன் ஒளிக்கதிர் மாலை பூண்ட, தோரணத்தில் நின்ற, பெரும் வேகமும் பெரும் உறுதியும் பெரும் வலிமையும் உடைய,',
        '0.20': 'பேரறிவும் பேரூக்கமும் பேருடலும் நீண்ட கைகளும் உடைய அவனை. அவனைக் கண்டதுமே எல்லாத் திசைகளிலும் நின்ற அவர்கள் அனைவரும்',
        '0.21': 'தங்கள் தங்கள் பயங்கர ஆயுதங்களுடன் எல்லாப் பக்கங்களிலிருந்தும் அவன் மேல் பாய்ந்தனர். துர்தரன் தாமரை இதழ் போன்ற, மஞ்சள் முனையுடைய வெண்மையான ஐந்து கூர்மையான இரும்பு அம்புகளை அவன் தலையில் எய்தான்.',
        '0.22': 'தலையில் அந்த ஐந்து அம்புகளால் துளைக்கப்பட்ட வானரன் முழங்கியவாறு பத்துத் திசைகளையும் ஒலிக்கச் செய்து வானில் தாவினான்.',
        '0.23': 'அப்போது பெருவலியனான வீரன் துர்தரன் தேரில், நாணேற்றிய வில்லுடன், நூற்றுக்கணக்கான அம்புகளைப் பொழிந்தவாறு அவனை நெருங்கினான்.',
        '0.24': 'மழைக்கால இறுதியில் காற்று மழைமேகத்தைத் தடுப்பது போல், வானில் அம்பு மழை பொழிந்த அவனைக் கபி தடுத்தான்.',
        '0.25': 'துர்தரனால் துன்புறுத்தப்பட்ட வலிய வாயுபுத்திரன் மீண்டும் முழங்கி உடலைப் பெருக்கினான்.',
        '0.26': 'தூரத்திலிருந்து திடீரென்று தாவி, பெரும் வேகமுடைய அந்தக் கபி மலையின் மேல் மின்னல் கூட்டம் விழுவது போல் துர்தரனின் தேரின் மேல் விழுந்தான்.',
        '0.27': 'அப்போது எட்டுக் குதிரைகளும் நசுங்கி, அச்சும் ஏர்க்காலும் முறிந்த தேரை விட்டு, துர்தரன் உயிரிழந்து தரையில் விழுந்தான்.',
        '0.28': 'அவன் தரையில் விழுந்ததைக் கண்டு, வெல்லமுடியாதவர்களும் பகைவரை அடக்குபவர்களுமான விரூபாக்ஷனும் யூபாக்ஷனும் சினந்து மேலே தாவினர்.',
        '0.29': 'திடீரென்று தாவி அவ்விருவரும் தெளிந்த வானில் நின்ற நீண்ட கைகளுடைய கபியின் மார்பில் முத்கரங்களால் தாக்கினர்.',
        '0.30': 'வேகமுடைய அவ்விருவரின் தாக்குதலை முறியடித்து, அந்த மகாபலன் வேகமான கருடனைப் போல் மீண்டும் தரையில் இறங்கினான்.',
        '0.31': 'ஒரு சால மரத்தை அடைந்து அதைப் பிடுங்கி, வாயுபுத்திரனான அந்த வானரன் அந்த இரு வீர அரக்கர்களையும் கொன்றான்.',
        '0.32': 'அப்போது வேகமுடைய வானரனால் அந்த மூவரும் கொல்லப்பட்டதை அறிந்து, பெரும் வேகமுடைய வலிய பிரகசன் சிரித்தவாறு அவனை நெருங்கினான்,',
        '0.33': 'வலிய பாசகர்ணனும் சினந்து சூலத்தை ஏந்தினான்; அவ்விருவரும் புகழ்மிக்க வானரப் புலியின் முன் ஒரு பக்கமாக நின்றனர்.',
        '0.34': 'பிரகசன் கூர்முனைப் பட்டிசத்தாலும், அரக்கன் பாசகர்ணன் சூலத்தாலும் அந்த வானர யானையைத் தாக்கினர்.',
        '0.35': 'அவர்களால் காயமுற்ற உறுப்புகளுடனும் இரத்தம் தோய்ந்த மயிர்களுடனும் அந்த வானரன் சினந்து, இளஞ்சூரியன் போல் ஒளிர்ந்தான்.',
        '0.36': 'விலங்குகள், பாம்புகள், மரங்களுடன் கூடிய மலைச் சிகரத்தைப் பெயர்த்து, வானர யானையான வீர ஹனுமான் அந்த இரு அரக்கர்களையும் தாக்கினான்; சிகரத்தால் நசுக்கப்பட்ட அவர்கள் எள்ளளவுத் துண்டுகளாயினர்.',
        '0.37': 'அந்த ஐந்து படைத்தலைவர்களும் மடிந்தபின், வானரன் எஞ்சிய படையை அழித்தான்.',
        '0.38': 'குதிரைகளால் குதிரைகளையும், யானைகளால் யானைகளையும், வீரர்களால் வீரர்களையும், தேர்களால் தேர்களையும் — ஆயிரம் கண்ணன் அசுரர்களை அழித்தது போல் அந்தக் கபி அழித்தான்.',
        '0.39': 'இறந்த குதிரைகள், யானைகள், அச்சு முறிந்த பெருந்தேர்கள், கொல்லப்பட்ட அரக்கர்கள் ஆகியவற்றால் சுற்றிலும் நிலத்தின் வழிகள் அடைபட்டன.',
        '0.40': 'படைகளுடனும் வாகனங்களுடனும் அந்த வீரப் படைத்தலைவர்களைப் போரில் கொன்று, அந்த வீரக் கபி உயிர்களின் அழிவுக்காலத்துக் காலனைப் போல் தருணத்தை எதிர்நோக்கி மீண்டும் தோரணத்தை அடைந்தான்.',
        '0.41': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்தாறாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-47': {
      verses: {
        '0.0': 'ஐந்து படைத்தலைவர்களும் பின்செல்வோர் வாகனங்களுடன் ஹனுமானால் கொல்லப்பட்டதைக் கேட்டு, அரசன் போருக்கு ஆர்வமுடன் எதிரே இருந்த குமாரன் அக்ஷனை நோக்கினான்.',
        '0.1': 'அந்தப் பார்வையால் தூண்டப்பட்ட, பொன்னால் அலங்கரிக்கப்பட்ட வில்லுடைய அந்த வீரன், வேள்விச் சபையில் சிறந்த அந்தணர்கள் அவிசால் வளர்த்த நெருப்பைப் போல் எழுந்தான்.',
        '0.2': 'அப்போது அந்த வலிய அரக்கர் சிரேஷ்டன் இளஞ்சூரியன் போல் ஒளிரும், புடம்போட்ட பொன்வலையால் மூடப்பட்ட பெரிய தேரில் ஏறி அந்த மகாகபியை நோக்கிச் சென்றான்.',
        '0.3': 'அந்தத் தேர் சேர்த்த தவத்தால் பெற்றது; புடம்போட்ட பொன்வலையால் அலங்கரிக்கப்பட்டது, பதாகைகளும் ரத்தினக் கொடிமரமும் உடையது, மனவேகமுடைய எட்டுச் சிறந்த குதிரைகள் நன்கு பூட்டப்பட்டது.',
        '0.4': 'தேவர் அசுரர்களாலும் வெல்ல முடியாத, தடையின்றிச் செல்லும், மின்னல் போல் ஒளிரும், வானில் செல்லும், முழுமையாக ஆயத்தமான, அம்பறாத்தூணிகளும் கட்டப்பட்ட எட்டு வாள்களும் வரிசையாக வைக்கப்பட்ட சக்தி தோமரங்களும் உடைய,',
        '0.5': 'எல்லாக் கருவிகளும் நிறைந்து விளங்கும், பொன்மாலைகள் உடைய, சந்திர சூரியர் போல் ஒளிரும், சூரியன் போன்ற அந்தத் தேரில் ஏறி, தேவர்களுக்கு நிகரான வீரமுடைய அவன் புறப்பட்டான்.',
        '0.6': 'குதிரைகள், யானைகள், பெருந்தேர்களின் ஒலியால் வானத்தையும் மலைகளுடன் கூடிய பூமியையும் நிரப்பியவாறு, திரண்ட படையுடன் அவன் தோரணத்தில் அமர்ந்திருந்த வல்லமையுள்ள கபியிடம் வந்தான்.',
        '0.7': 'யுகமுடிவில் உயிர்களை அழிக்கும் காலத்தீயைப் போல் நின்ற அந்தக் கபியை நெருங்கி, சிங்கக் கண்களுடைய அக்ஷன் வியப்பும் பரபரப்பும் கொண்டு பெருமதிப்புடன் அவனை நோக்கினான்.',
        '0.8': 'மகாத்மாவான அந்தக் கபியின் வேகத்தையும், பகைவர் மீதான வீரத்தையும், தன் வலிமையையும் எண்ணிப் பார்த்து, வலிய ராவணபுத்திரன் யுகமுடிவுச் சூரியன் போல் பெருகினான்.',
        '0.9': 'சினமுற்று, போரில் தடுக்க முடியாத அந்த வீரத்தைக் கண்டு அவன் உறுதியாக நின்று, மனத்தை ஒருமுகப்படுத்தி, மூன்று கூர்மையான அம்புகளால் ஹனுமானைப் போருக்குத் தூண்டினான்.',
        '0.10': 'அப்போது வில்லும் அம்புகளும் ஏந்திய அக்ஷன், செருக்குடைய, களைப்பை வென்ற, பகைவரை வெல்லத் தகுந்த, ஊக்கம் நிறைந்த அந்தக் கபியை நோக்கினான்.',
        '0.11': 'பொன் கழுத்தணி, தோள்வளை, அழகிய குண்டலங்கள் அணிந்த விரைந்த வீரமுடைய அவன் கபியை எதிர்கொண்டான்; அவ்விருவரின் மோதல் நிகரற்றது, தேவர் அசுரர்களுக்கும் கலக்கமூட்டுவது.',
        '0.12': 'கபிக்கும் குமாரனுக்கும் இடையிலான அந்த வீரப்போரில் பூமி அலறியது, சூரியன் வெப்பம் தரவில்லை, காற்று வீசவில்லை, மலை அதிர்ந்தது, வானம் முழங்கியது, கடல் கொந்தளித்தது.',
        '0.13': 'அப்போது குறிவைத்தல், தொடுத்தல், விடுத்தல் ஆகியவற்றின் நுட்பம் அறிந்த அந்த வீரன், அழகிய முனையும் பொன் இறகும் உடைய, நஞ்சுள்ள பாம்புகள் போன்ற மூன்று அம்புகளால் கபியின் தலையில் தாக்கினான்.',
        '0.14': 'தலையில் ஒருசேரப் பதிந்த அந்த அம்புகளால் இரத்தம் வழிய, இரத்தம் தோய்ந்து சுழலும் கண்களுடன், அம்புகளே கதிர்களாக அவன் புதிதாக உதித்த கதிர்மாலைச் சூரியனைப் போல் விளங்கினான்.',
        '0.15': 'அப்போது வானர அரசனின் சிறந்த அமைச்சன், உயர்ந்த விசித்திர ஆயுதங்களும் விசித்திர வில்லும் உடைய அந்த அரசகுமாரனைப் போரில் கண்டு மகிழ்ந்து போர் ஆர்வத்தால் நிறைந்தான்.',
        '0.16': 'மந்தர மலைச் சிகரத்தில் உள்ள சூரியனைப் போல், பெருகும் சினத்துடனும் வலிமை வீரத்துடனும் அவன், தன் கண்களின் நெருப்புக் கதிர்களால் படை வாகனங்களுடன் குமாரன் அக்ஷனை எரிப்பது போல் இருந்தான்.',
        '0.17': 'அப்போது வில்லே வானவில்லாக, அம்புகளே மழையாக இருந்த அந்த அரக்க மேகம், சிறந்த மலையின் மேல் மேகம் மழை பொழிவது போல், மலைபோன்ற கபீஸ்வரன் மீது விரைந்து அம்புகளைப் பொழிந்தது.',
        '0.18': 'அப்போது போரில் கடும் வீரமுடைய, ஒளியும் வலிமையும் ஆற்றலும் அம்புகளும் பெருகிய குமாரன் அக்ஷனைக் கண்டு, கபி மகிழ்ச்சியுடன் இடிமுழக்கம் போல் முழங்கினான்.',
        '0.19': 'இளமையின் காரணமாகப் போரில் வீரச்செருக்குக் கொண்டு, பெருகிய சினமும் இரத்தம் போன்ற சிவந்த கண்களும் உடைய அவன், புல்லால் மூடப்பட்ட பெரிய கிணற்றை யானை நெருங்குவது போல், நிகரற்ற கபியை எதிர்கொண்டான்.',
        '0.20': 'அவன் வலுவாக எய்த அம்புகளால் தாக்கப்பட்ட கபி இடிமுழக்கம் போல் முழங்கி, கைகளையும் தொடைகளையும் வீசிப் பயங்கரமாகத் தோன்றியவாறு, வானைப் பிளப்பது போல் விரைந்து மேலே தாவினான்.',
        '0.21': 'அவன் மேலே தாவியதும், வலியவனும் வீரனும் அரக்கர்களில் சிறந்தவனும் தேர்வீரர்களில் மேலானவனுமான அக்ஷன், மேகம் மலையின் மேல் ஆலங்கட்டி பொழிவது போல் அம்புகளைப் பொழிந்தவாறு தேரில் அவனைத் துரத்தினான்.',
        '0.22': 'அவனுடைய அம்புகளைத் தவிர்த்தவாறு, மனவேகமுடைய, போரில் கடும் வீரமுடைய அந்த வீரக்கபி அம்புகளுக்கு இடையே காற்றைப் போல் நுழைந்து வான்வழியில் உலவினான்.',
        '0.23': 'வில்லேந்தி, போர் ஆர்வத்துடன், பலவகைச் சிறந்த அம்புகளால் வானை மூடிய அக்ஷனை வாயுபுத்திரன் பெருமதிப்புடன் நோக்கிச் சிந்திக்கலானான்.',
        '0.24': 'அப்போது மகாத்மாவான அந்தச் சிறந்த குமாரனின் அம்புகளால் மார்பு பிளக்கப்பட்ட நீண்ட கைகளுடைய கபி முழங்கி, காரியத்தின் நுட்பம் அறிந்தவனாகப் போரில் காட்ட வேண்டிய வீரத்தைப் பற்றிச் சிந்தித்தான்:',
        '0.25': '“இளஞ்சூரியன் போல் ஒளிரும் இந்த மகாபலன் சிறுவனைப் போலன்றிப் பெரும் செயல் செய்கிறான்; எல்லாப் போர்க்கலைகளிலும் தேர்ந்த இவனைக் கொல்ல என் மனம் ஒப்பவில்லை.',
        '0.26': '“இவன் மகாத்மா, வீரத்தில் பெரியவன், போரில் ஒருமுக மனமும் மிகுந்த பொறுமையும் உடையவன்; செயல் குணங்களின் மேன்மையால் இவன் நாகர், யக்ஷர், முனிவர்களால் போற்றப்படுபவன் என்பதில் ஐயமில்லை.',
        '0.27': '“வீரமும் ஊக்கமும் பெருகிய மனத்துடன் இவன் என் முன் நேராக நின்று நோக்குகிறான்; விரைந்து செயல்படும் இவனுடைய வீரம் தேவர் அசுரர்களின் மனத்தையும் நடுங்கச் செய்யும்.',
        '0.28': '“புறக்கணித்தால் இவன் நிச்சயம் என்னை வெல்வான், ஏனெனில் போரில் இவனுடைய வீரம் பெருகுகிறது. இன்று இவனைக் கொல்வதே எனக்குச் சரியெனப் படுகிறது; வளரும் நெருப்பைப் புறக்கணிக்கக் கூடாது.”',
        '0.29': 'இவ்வாறு எதிரியின் வேகத்தை ஆராய்ந்து தன் செயல்முறையை முடிவுசெய்து, அந்த மகாபலன் அப்போது வேகத்தைக் கூட்டி அவனைக் கொல்லத் தீர்மானித்தான்.',
        '0.30': 'வாயுபுத்திரனான அந்த வீரக்கபி வான்வழியிலேயே, நன்கு பழக்கப்பட்ட, பாரம் தாங்கும், திரும்புவதில் வல்ல அவனுடைய அந்த எட்டுச் சிறந்த பெரும் குதிரைகளையும் உள்ளங்கை அடிகளால் கொன்றான்.',
        '0.31': 'அப்போது வானர அரசனின் அமைச்சனின் உள்ளங்கை அடியால் வீழ்த்தப்பட்ட அந்தப் பெருந்தேர், இருக்கை உடைந்து, ஏர்க்கால் புரண்டு, குதிரைகள் இறந்து, வானிலிருந்து தரையில் விழுந்தது.',
        '0.32': 'அந்தத் தேரை விட்டு, அந்த மகாரதன் வில்லும் வாளும் ஏந்தி, யோகத்தால் உடலைத் துறந்து மருத்துகளின் உலகுக்கு எழும் கடுந்தவ முனிவனைப் போல் வானுக்குத் தாவினான்.',
        '0.33': 'அப்போது காற்றின் வேகமும் வீரமும் உடைய கபி, கருடன், காற்று, சித்தர்கள் உலவும் வானில் திரிந்த அவனை நெருங்கி, படிப்படியாக அவனுடைய கால்களை இறுகப் பற்றினான்.',
        '0.34': 'பறவைகளின் அரசன் கருடன் பெரும் பாம்பைப் பற்றுவது போல் அவனை ஆயிரம் முறை சுழற்றி, தந்தைக்கு நிகரான வீரமுடைய அந்த வானர சிரேஷ்டன் போரில் அவனை வேகமாகத் தரையில் அடித்தான்.',
        '0.35': 'கைகள், தொடைகள், இடுப்பு, மார்பு உடைந்து, இரத்தம் வழிந்து, எலும்புகளும் கண்களும் நசுங்கி, மூட்டுகள் பிளந்து, நரம்புகள் சிதறி, அந்த அரக்கன் வாயுபுத்திரனால் கொல்லப்பட்டுத் தரையில் கிடந்தான்.',
        '0.36': 'அவனைத் தரையில் நசுக்கி அந்த மகாகபி அரக்கர் தலைவனுக்குப் பெரும் அச்சத்தை உண்டாக்கினான். குமாரன் கொல்லப்பட்டபோது, அங்கே கூடியிருந்த வானுலவும் மகரிஷிகளும், யக்ஷர் நாகர்களுடன் கூடிய பூதங்களும், இந்திரனுடன் தேவர்களும் மிகுந்த வியப்புடன் அந்தக் கபியை நோக்கினர்.',
        '0.37': 'இந்திரனின் மகனைப் போன்ற, இரத்தம் போல் சிவந்த கண்களுடைய குமாரன் அக்ஷனைப் போரில் கொன்று, அந்த வீரன் உயிர்களின் அழிவுக்காலத்துக் காலனைப் போல் தருணத்தை எதிர்நோக்கி மீண்டும் அதே தோரணத்தை அடைந்தான்.',
        '0.38': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்தேழாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-48': {
      verses: {
        '0.0': 'குமாரன் அக்ஷன் ஹனுமானால் கொல்லப்பட்டபோது, வலிய அரக்கர் தலைவன் மனத்தை நிலைப்படுத்தி, சினத்துடன் தேவர்க்கு நிகரான இந்திரஜித்துக்குக் கட்டளையிட்டான்:',
        '0.1': '“நீ அஸ்திரங்களை அறிந்தவன், ஆயுதம் ஏந்துவோரில் சிறந்தவன், தேவர் அசுரர்களுக்கும் துயரம் தருபவன்; இந்திரனுடன் தேவர்களிடம் உன் செயல் காணப்பட்டது; பிரம்மனை வழிபட்டு நீ அஸ்திரங்களைப் பெற்றிருக்கிறாய்.',
        '0.2': '“உன் அஸ்திர வலிமையை எதிர்கொண்ட மருத்கணங்களுடன் கூடிய தேவர்கள், தேவேந்திரனைச் சார்ந்திருந்தும் போரில் நிற்க முடியவில்லை.',
        '0.3': '“மூவுலகிலும் போரில் உன்னால் களைப்படையாதவன் எவனும் இல்லை. புயவலியால் காக்கப்பட்டு, தவத்தால் பாதுகாக்கப்பட்டு, இடம் காலம் அறிந்த நீயே அறிவாளிகளில் சிறந்தவன்.',
        '0.4': '“போரில் உனக்கு முடியாத செயல் இல்லை; ஆழ்ந்து ஆலோசித்த மந்திராலோசனையில் உனக்குச் செய்யக்கூடாதது இல்லை; உன் அஸ்திர வலிமையையும் பலத்தையும் அறியாதவன் மூவுலகிலும் இல்லை.',
        '0.5': '“உன் தவவலிமையும் வீரமும் போரில் அஸ்திர வலிமையும் எனக்கு ஏற்றவையே. போர் நெருக்கடியில் உன்னைச் சார்ந்தால் என் மனம் கவலையின்றி, முடிவைப் பற்றி உறுதியாக இருக்கும்.',
        '0.6': '“கிங்கரர் அனைவரும் கொல்லப்பட்டனர்; அரக்கன் ஜம்புமாலியும், வீரர்களான அமைச்சர் மகன்களும், ஐந்து படைத்தலைவர்களும் கொல்லப்பட்டனர்;',
        '0.7': '“குதிரை, யானை, தேர்களுடன் கூடிய வளமான படைகளும், உன் அன்புச் சகோதரன் குமாரன் அக்ஷனும் கொல்லப்பட்டனர். பகைவரை அழிப்பவனே, உன்மீது எனக்குள்ள நம்பிக்கை அவர்கள் மீது இல்லை.',
        '0.8': '“இந்தப் பெரும் படை அழிந்ததையும் கபியின் ஆற்றலையும் வீரத்தையும் கண்டு, உன் வலிமையையும் ஆராய்ந்து, உன் பலத்துக்கு ஏற்ற வேகத்தைக் காட்டு.',
        '0.9': '“அஸ்திரம் ஏந்துவோரில் சிறந்தவனே, நீ நெருங்கியதும் பகைவன் அடங்கி நம் படையின் அழிவு நிற்கும்படி, உன் வலிமையையும் பகைவன் வலிமையையும் ஆராய்ந்து செயலைத் தொடங்கு.',
        '0.10': '“வீரனே, கூட்டம் கூட்டமாகப் படைகளை அனுப்புவது பயனில்லை; பெரும் வலிமையுடைய வஜ்ராயுதத்தை ஏந்துவதும் அல்ல; காற்றைப் போன்ற அவனுடைய வேகத்துக்கு அளவில்லை; நெருப்பைப் போன்ற அவனைச் சாதாரண வழிகளால் கொல்ல முடியாது.',
        '0.11': '“இதை நன்கு ஆராய்ந்து, உன் வலிமைக்கு ஏற்ற செயலுக்காக மனத்தை ஒருமுகப்படுத்தி, உன் வில்லின் தெய்வீக ஆற்றலை நினைவுகூர்ந்து, சென்று தவறாத செயலைத் தொடங்கு.',
        '0.12': '“அறிவில் சிறந்தவனே, உன்னை இதற்கு அனுப்புவது என் விருப்பமல்ல; ஆனால் அரசநெறியும் க்ஷத்திரிய நெறியும் இதுவே என்று கருதப்படுகிறது.',
        '0.13': '“பகைவரை அடக்குபவனே, போரில் பலவகை ஆயுதங்களின் திறமையை நிச்சயம் அறிந்திருக்க வேண்டும்; போரில் வெற்றியை விரும்ப வேண்டும்.”',
        '0.14': 'தந்தையின் அந்தச் சொற்களைக் கேட்டு, தக்ஷனின் மக்களைப் (தேவர்களைப்) போன்ற ஆற்றலுடைய அந்த வீரன் போருக்கு மனம் உறுதிகொண்டு, விரைந்து தன் தலைவனை வலம் வந்தான்.',
        '0.15': 'அப்போது தன் அன்புத் தோழர்களால் கௌரவிக்கப்பட்ட இந்திரஜித் போர் ஆர்வத்துடன் போருக்குப் புறப்பட்டான்.',
        '0.16': 'பொலிவுடைய, தாமரை போன்ற அகன்ற கண்களுடைய, மிகுந்த ஒளியுடைய அரக்கர் தலைவனின் மகன் பௌர்ணமிக் கடல் போல் பொங்கிப் புறப்பட்டான்.',
        '0.17': 'இந்திரனுக்கு நிகரான, தாங்க முடியாத வேகமுடைய இந்திரஜித், பறவையரசனுக்கு நிகரான வேகமும் கூர்மையான கோரைப்பற்களும் உடைய நான்கு புலிகள் பூட்டிய தேரில் ஏறினான்.',
        '0.18': 'வில்லாளிகளில் சிறந்தவனும், ஆயுதங்களை அறிந்தவனும், அஸ்திரம் அறிந்தோரில் மேலானவனுமான அந்தத் தேர்வீரன், ஹனுமான் இருந்த இடத்துக்குத் தேரில் விரைந்து சென்றான்.',
        '0.19': 'அவனுடைய தேரின் முழக்கத்தையும் வில்நாணின் ஒலியையும் கேட்டு அந்த வானர வீரன் மேலும் மகிழ்ந்தான்.',
        '0.20': 'வில்லையும் கூர்முனை அம்புகளையும் எடுத்துக்கொண்டு, போரில் வல்ல இந்திரஜித் ஹனுமானை நோக்கிச் சென்றான்.',
        '0.21': 'அவன் மகிழ்ச்சியுடன் அம்புகளைக் கையிலேந்திப் போருக்குப் புறப்பட்டபோது எல்லாத் திசைகளும் கலங்கின; கொடிய விலங்குகள் பலவாறு ஊளையிட்டன.',
        '0.22': 'நாகர், யக்ஷர், மகரிஷிகள், வானுலவும் சித்தர்கள் அங்கே கூடினர்; பறவைக் கூட்டங்கள் வானை மூடி மிகுந்த பரபரப்புடன் உரக்கக் கூவின.',
        '0.23': 'இந்திரக் கொடியுடைய அந்தத் தேர் விரைந்து வருவதைக் கண்டு வேகமுடைய கபி பெருமுழக்கமிட்டு உடலைப் பெருக்கினான்.',
        '0.24': 'அந்தத் தெய்வீகத் தேரில் அமர்ந்த, விசித்திர வில்லுடைய இந்திரஜித் மின்னலின் இடியொலி போன்ற ஓசையுடன் வில்லை நாணொலித்தான்.',
        '0.25': 'அப்போது மிகக் கடும் வேகமும் பெரும் வலிமையும் உடைய, போரில் அச்சமற்ற கபியும் அரக்கர் தலைவனின் மகனும், பகை கொண்ட தேவேந்திரனும் அசுரேந்திரனும் போல் மோதினர்.',
        '0.26': 'உடலைப் பெருக்கிய அளவிட முடியாத ஹனுமான், போரில் மதிக்கப்பட்ட அந்த வீர மகாரத வில்லாளியின் அம்பு வேகத்தைத் தடுத்து, தந்தையின் வழியான வானில் உலவினான்.',
        '0.27': 'அப்போது பகைவீரர்களைக் கொல்லும் அந்த வீரன், நீண்ட, கூர்முனையுடைய, அழகிய இறகுகளும் பொன் வேலைப்பாட்டு அடிப்பகுதியும் உடைய, வஜ்ரம் போல் வேகமான அம்புகளைத் தொடர்ந்து எய்தான்.',
        '0.28': 'அந்தத் தேரின் ஒலியையும், மிருதங்கம், பேரிகை, பறை ஆகியவற்றின் ஒலியையும், இழுக்கப்படும் வில்லின் ஓசையையும் கேட்டு கபி மீண்டும் மேலே தாவினான்.',
        '0.29': 'குறி தவறாத அந்த வில்லாளியின் குறியைத் தவிர்த்தவாறு மகாகபி அம்புகளுக்கு இடையே விரைந்து சுழன்றான்.',
        '0.30': 'மீண்டும் அவனுடைய அம்புகளின் முன்னே வந்து, பின் வாயுபுத்திரன் ஹனுமான் கைகளை விரித்து மேலே பறந்தான்.',
        '0.31': 'வேகமுடையவர்களும் போர்க்கலையில் தேர்ந்தவர்களுமான அவ்விருவரும் எல்லா உயிர்களின் மனத்தையும் கவரும் சிறந்த போரைச் செய்தனர்.',
        '0.32': 'அரக்கனால் ஹனுமானிடம் எந்தப் பலவீனத்தையும் காண முடியவில்லை, மாருதியாலும் அந்த மகாத்மாவிடம் காண முடியவில்லை; தேவர்க்கு நிகரான வீரமுடைய அவ்விருவரும் ஒருவருக்கொருவர் வெல்ல முடியாதவர்களாயினர்.',
        '0.33': 'அப்போது குறி தவறி, தவறாத அம்புகள் வீணாக விழ, மனத்தை ஒருமுகப்படுத்திய அந்த மகாத்மா ஆழ்ந்த சிந்தனையில் ஆழ்ந்தான்.',
        '0.34': 'அப்போது அரக்கர் அரசனின் மகன் அந்தக் கபி கொல்ல முடியாதவன் என்று கண்டு, அந்த வானர வீரர் தலைவனை எப்படிப் பிடிப்பது என்று எண்ணினான்.',
        '0.35': 'அப்போது அஸ்திரம் அறிந்தோரில் சிறந்த, மிகுந்த ஒளியுடைய அந்த வீரன் அந்த வானர சிரேஷ்டன் மீது பிதாமகனின் (பிரம்மனின்) அஸ்திரத்தைத் தொடுத்தான்.',
        '0.36': 'இவன் கொல்ல முடியாதவன் என்று அறிந்து, அஸ்திர நுட்பம் அறிந்த இந்திரஜித் நீண்ட கைகளுடைய அந்த வாயுபுத்திரனை அந்த அஸ்திரத்தால் கட்டினான்.',
        '0.37': 'அரக்கனால் அந்த அஸ்திரத்தால் கட்டப்பட்ட அந்த வானரன் அசைவற்று தரையில் விழுந்தான்.',
        '0.38': 'அப்போது அந்த அஸ்திரக் கட்டை அறிந்து, இறைவனின் (பிரம்மனின்) ஆற்றலால் வேகம் இழந்த அந்த வானர வீரன் தனக்குப் பிதாமகன் அருளிய அனுக்கிரகத்தை நினைத்தான்.',
        '0.39': 'அப்போது சுயம்புவின் மந்திரங்களால் அபிமந்திரிக்கப்பட்ட பிரம்மாஸ்திரத்தையும், பிதாமகனிடமிருந்து தனக்குக் கிடைத்த வரத்தையும் ஹனுமான் எண்ணினான்.',
        '0.40': '“உலககுருவின் ஆற்றலால் இந்தக் கட்டிலிருந்து விடுபடும் சக்தி எனக்கில்லை. இந்த அஸ்திரக் கட்டு இவ்வாறு விதிக்கப்பட்டுள்ளதால், நான் சுயம்புவுக்குக் கீழ்ப்படிய வேண்டும்.”',
        '0.41': 'அஸ்திரத்தின் வலிமையையும் தன்மீது பிதாமகனின் அருளையும் ஆராய்ந்து, விடுபடும் ஆற்றலைப் பற்றி எண்ணி, அந்தக் கபி பிதாமகனின் கட்டளைக்குக் கீழ்ப்படிந்தான்.',
        '0.42': '“அஸ்திரத்தால் கட்டப்பட்டிருந்தும் எனக்கு அச்சம் உண்டாகவில்லை, ஏனெனில் பிதாமகன், மகேந்திரன், வாயு ஆகியோரால் நான் காக்கப்படுகிறேன்.',
        '0.43': '“அரக்கர்களால் பிடிக்கப்படுவதிலும் எனக்குப் பெரும் நன்மை தெரிகிறது — அரக்கர் அரசனுடன் உரையாடல். ஆகவே பகைவர்கள் என்னைப் பிடிக்கட்டும்.”',
        '0.44': 'உறுதியான நோக்கமுடைய, ஆராய்ந்து செயல்படும் அந்தப் பகைவீரரைக் கொல்பவன் அசைவை நிறுத்தினான்; பாய்ந்து வந்த பகைவர்களால் பிடிக்கப்பட்டு, அவர்கள் இகழ்ந்தபோது முழங்கினான்.',
        '0.45': 'பகைவரை அடக்குபவன் அசைவற்றிருப்பதைக் கண்டு அரக்கர்கள் அவனைச் சணல் கயிறுகளாலும் முறுக்கிய மரப்பட்டை நார்களாலும் கட்டினர்.',
        '0.46': 'பகைவரால் கட்டப்படுவதையும் அந்த வீரர்களால் இகழப்படுவதையும் அவன் ஏற்றுக்கொண்டான்; “அரக்கர் அரசன் ஆர்வத்தால் என்னைக் காண விரும்பலாம்” என்பது அவனுடைய உறுதியான நோக்கம்.',
        '0.47': 'அந்த நாரால் கட்டப்பட்டதும் அந்த வலியவன் அஸ்திரத்திலிருந்து விடுபட்டான்; ஏனெனில் அஸ்திரக் கட்டு வேறு கட்டைப் பொறுக்காது.',
        '0.48': 'அப்போது வீரன் இந்திரஜித், மரநாரால் கட்டப்பட்ட அந்தக் கபி சிரேஷ்டன் அஸ்திரத்திலிருந்து விடுபட்டதைக் கண்டு, “வேறொன்றால் கட்டினால் அஸ்திரம் விலகிவிடும்” என்று கவலைகொண்டான்.',
        '0.49': '“ஐயோ, பெரும் செயல் வீணாயிற்று! அரக்கர்கள் மந்திரத்தின் நடைமுறையை ஆராயவில்லை. ஓர் அஸ்திரம் விலகினால் வேறு அஸ்திரம் செயல்படாது; நாம் அனைவரும் ஆபத்தில் இருக்கிறோம்.”',
        '0.50': 'அஸ்திரத்திலிருந்து விடுபட்டிருந்தும் ஹனுமான் அதை வெளிக்காட்டவில்லை; அந்தக் கட்டுகளால் வருந்தியவாறு அரக்கர்களால் இழுத்துச் செல்லப்பட்டான்.',
        '0.51': 'காலனைப் போன்ற முஷ்டிகளுடைய கொடிய அரக்கர்களால் அடிக்கப்பட்டவாறு அந்த வானரன் அரக்கர் அரசனின் அருகே இழுத்துச் செல்லப்பட்டான்.',
        '0.52': 'அப்போது இந்திரஜித், அவன் அஸ்திரத்திலிருந்து விடுபட்டு நார்க்கயிறுகளால் கட்டப்பட்டிருப்பதைக் கண்டு, அந்த வலிய வானர வீரனை அங்கே சபையுடன் இருந்த அரசனுக்குக் காட்டினான்.',
        '0.53': 'மதயானை போல் கட்டப்பட்ட அந்தக் கபி சிரேஷ்டனைப் பற்றி அரக்கர்கள் அரக்கர் அரசன் ராவணனிடம் தெரிவித்தனர்.',
        '0.54': '“இவன் யார்? யாருடையவன்? எங்கிருந்து வந்தான்? இவனுடைய காரியம் என்ன? இவனுக்கு ஆதரவு யார்?” — அவனைக் கண்டு அரக்க வீரர்களிடையே இத்தகைய பேச்சுகள் எழுந்தன.',
        '0.55': '“இவனைக் கொல்லுங்கள்!”, “எரியுங்கள்!”, “தின்னுங்கள்!” — என்று அங்கே சினந்த வேறு அரக்கர்கள் ஒருவருக்கொருவர் கூறினர்.',
        '0.56': 'விரைவில் வழியைக் கடந்த அந்த மகாத்மா, அங்கே அரக்கர் தலைவனின் பாதங்களின் அருகே அரசனின் முதிய பணியாளர்களையும், பெரும் ரத்தினங்களால் அலங்கரிக்கப்பட்ட மண்டபத்தையும் கண்டான்.',
        '0.57': 'மிகுந்த ஒளியுடைய ராவணன், விகார உருவமுடைய அரக்கர்களால் அங்குமிங்கும் இழுக்கப்பட்ட அந்தக் கபி சிரேஷ்டனைக் கண்டான்.',
        '0.58': 'கபி சிரேஷ்டனும் ஒளியும் வலிமையும் கொண்டு சுட்டெரிக்கும் சூரியன் போல் விளங்கிய அரக்கர் தலைவனைக் கண்டான்.',
        '0.59': 'சினத்தால் செந்நிறக் கண்களைச் சுழற்றிய பத்துத்தலையன் அந்தக் கபியைக் கூர்ந்து நோக்கி, அங்கே அமர்ந்திருந்த குலத்திலும் ஒழுக்கத்திலும் மூத்த முதன்மை அமைச்சர்களுக்கு அவனைப் பற்றிக் கட்டளையிட்டான்.',
        '0.60': 'அவர்கள் முறைப்படி அவனுடைய வருகையின் நோக்கத்தையும் அதன் மூலக் காரணத்தையும் கேட்க, கபி “வானர அரசனிடமிருந்து தூதனாக வந்திருக்கிறேன்” என்று தெரிவித்தான்.',
        '0.61': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்தெட்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-49': {
      verses: {
        '0.0': 'அப்போது கடும் வீரமுடைய ஹனுமான் நடந்த செயலால் வியப்புற்று, சினத்தால் சிவந்த கண்களுடன் அரக்கர் தலைவனை நோக்கினான்.',
        '0.1': 'அவன் முத்துவலைகளால் சூழப்பட்ட விலைமதிப்பற்ற ஒளிரும் பொன்மகுடத்தால் பேரொளியுடன் விளங்கினான்;',
        '0.2': 'வைரங்களும் விலையுயர்ந்த மணிகளும் பதித்த, மனத்தாலேயே உருவாக்கப்பட்டது போன்ற விசித்திரப் பொன் அணிகலன்களுடன் இருந்தான்;',
        '0.3': 'விலையுயர்ந்த பட்டாடை அணிந்து, செஞ்சந்தனம் பூசி, விசித்திரமான பலவகைச் சித்திர அலங்காரங்களால் நன்கு அலங்கரிக்கப்பட்டிருந்தான்;',
        '0.4': 'அழகானவையும் அச்சமூட்டுபவையுமான சிவந்த கண்களாலும், ஒளிரும் கூர்மையான பெருங்கோரைப்பற்களாலும், தொங்கும் உதடுகளாலும் விசித்திரமாகத் தோன்றினான்;',
        '0.5': 'பலவகைப் பாம்புகள் நிறைந்த சிகரங்களுடைய மந்தர மலையைப் போல், பத்துத் தலைகளுடன் விளங்கிய பெரும் வலிமையுடைய வீரன்;',
        '0.6': 'மைக்குவியல் போல் கரிய, மார்பில் ஒளிரும் ஆரமும் முழுநிலவு போன்ற முகமும் உடைய அவன், இளஞ்சூரியனுடன் கூடிய மேகம் போல் இருந்தான்;',
        '0.7': 'தோள்வளைகள் பூண்ட, சிறந்த சந்தனம் பூசிய, ஒளிரும் அங்கதங்கள் உடைய அவனுடைய கைகள் பயங்கரமான ஐந்துதலைப் பாம்புகளைப் போல் இருந்தன;',
        '0.8': 'ரத்தினங்கள் பதித்த, சிறந்த விரிப்புகள் விரித்த பெரிய விசித்திரமான பளிங்கு உயர் அரியணையில் சுகமாக அமர்ந்திருந்தான்;',
        '0.9': 'மிகுதியாக அலங்கரித்துக்கொண்ட, சாமரங்களைக் கையிலேந்திய இளம்பெண்கள் சுற்றிலும் அருகில் இருந்து அவனுக்குப் பணிவிடை செய்தனர்;',
        '0.10': 'மந்திராலோசனையின் நுட்பம் அறிந்த அமைச்சர்களான துர்தரன், பிரஹஸ்தன், அரக்கன் மகாபார்ஸ்வன், அமைச்சன் நிகும்பன் —',
        '0.11': 'இந்த நான்கு அரக்கர்களும் அருகில் அமர்ந்திருக்க, வலிமைச் செருக்குடைய அவன் நான்கு கடல்களால் சூழப்பட்ட உலகம் முழுவதையும் போல் தோன்றினான்.',
        '0.12': 'மந்திர நுட்பம் அறிந்த அமைச்சர்களும் நலம் நாடும் பிற ஆலோசகர்களும், தேவர்கள் தேவேந்திரனைத் தேற்றுவது போல் அவனைத் தேற்றிக்கொண்டிருந்தனர்.',
        '0.13': 'மேரு சிகரத்தைச் சூழ்ந்த நீர் நிறைந்த மேகம் போல், மிகுந்த ஒளியுடைய அரக்கர் தலைவனை ஹனுமான் கண்டான்.',
        '0.14': 'கடும் வீரமுடைய அந்த அரக்கர்களால் துன்புறுத்தப்பட்டாலும், அவன் மிகுந்த வியப்புடன் அரக்கர் தலைவனை நோக்கினான்.',
        '0.15': 'ஒளிர்ந்த அரக்கர் தலைவனைக் கண்டு, அவனுடைய ஒளியால் திகைத்த ஹனுமான் மனத்தில் இவ்வாறு எண்ணினான்:',
        '0.16': '“ஆகா, என்ன அழகு! என்ன துணிவு! என்ன வலிமை! என்ன ஒளி! இந்த அரக்கர் அரசன் எல்லா நல்லிலக்கணங்களும் பொருந்தியிருப்பது எத்தகைய வியப்பு!',
        '0.17': '“இவனிடம் அதர்மம் வலுவாக இல்லாதிருந்தால், இந்த அரக்கர் தலைவன் இந்திரனுடன் கூடிய தேவலோகத்துக்கும் காவலனாக இருந்திருப்பான்.',
        '0.18': '“உலகம் பழிக்கும் இவனுடைய கொடிய இரக்கமற்ற செயல்களால், தேவர் தானவர்களுடன் எல்லா உலகங்களும் இவனுக்கு அஞ்சுகின்றன.',
        '0.19': '“சினந்தால் இவன் உலகையே ஒரே கடலாக்க வல்லவன்.” அளவற்ற வலிமையுடைய அரக்கர் அரசனின் ஆற்றலைக் கண்டு அறிவுடைய கபி இவ்வாறு பலவாறு சிந்தித்தான்.',
        '0.20': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் நாற்பத்தொன்பதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-50': {
      verses: {
        '0.0': 'எதிரே நின்ற பழுப்புக் கண்களுடைய அந்தக் கபியைப் பார்த்து, உலகங்களை அழவைக்கும் நீண்ட கைகளுடைய ராவணன் பெருஞ்சினம் கொண்டான்.',
        '0.1': 'ஐயத்தால் கலங்கிய மனத்துடன், ஒளியால் சூழப்பட்ட அந்தக் கபீந்திரனைப் பற்றி அவன் எண்ணினான்: “இவன் சாக்ஷாத் பகவான் நந்தியே இங்கே வந்திருக்கிறாரோ,',
        '0.2': '“முன்பு கைலாசத்தில் நான் சிரித்தபோது என்னைச் சபித்தவர்? அவரே வானர உருவில் இருக்கிறாரா, அல்லது அசுரன் பாணனா?”',
        '0.3': 'சினத்தால் சிவந்த கண்களுடைய அந்த அரசன், அமைச்சர்களில் சிறந்த பிரஹஸ்தனிடம் காலத்துக்கு ஏற்ற பொருள்நிறைந்த இந்தச் சொற்களைக் கூறினான்:',
        '0.4': '“இந்தத் தீயவனிடம் கேளுங்கள்: எங்கிருந்து, எதற்காக வந்தான்? சோலையை அழித்ததிலும் அரக்கர்களை அச்சுறுத்தியதிலும் இவனுடைய நோக்கம் என்ன?',
        '0.5': '“வெல்ல முடியாத என் நகருக்கு வந்ததில் இவனுடைய நோக்கம் என்ன? போரிட்டதில் என்ன காரணம்? இந்தத் தீய மதியனிடம் கேளுங்கள்.”',
        '0.6': 'ராவணனின் சொற்களைக் கேட்டு பிரஹஸ்தன் கூறினான்: “கபியே, ஆறுதல் கொள், உனக்கு நலம் உண்டாகட்டும்; நீ அஞ்ச வேண்டியதில்லை.',
        '0.7': '“உன்னை இந்திரன் ராவணனின் இருப்பிடத்துக்கு அனுப்பியிருந்தால் உண்மையைச் சொல்; வானரனே, அஞ்சாதே, நீ விடுவிக்கப்படுவாய்.',
        '0.8': '“அல்லது நீ குபேரனுடையவனாகவோ, யமனுடையவனாகவோ, வருணனுடையவனாகவோ இந்த அழகிய உருவெடுத்து எங்கள் இந்த நகருக்குள் நுழைந்தாயோ,',
        '0.9': '“அல்லது வெற்றியை விரும்பும் விஷ்ணுவால் அனுப்பப்பட்ட தூதனோ — ஏனெனில் உன் ஒளி வானரனுடையதல்ல; உருவம் மட்டுமே வானரனுடையது.',
        '0.10': '“இப்போது உண்மையைச் சொல், வானரனே, அப்போது நீ விடுவிக்கப்படுவாய்; பொய் சொன்னால் உன் உயிர் பிழைப்பது அரிது.',
        '0.11': '“அல்லது எந்தக் காரணத்துக்காக ராவணனின் இருப்பிடத்தில் நுழைந்தாய் என்று சொல்.” இவ்வாறு கேட்கப்பட்ட வானர சிரேஷ்டன் அப்போது அரக்கர் கணங்களின் தலைவனிடம் கூறினான்:',
        '0.12': '“நான் இந்திரனுடையவனல்ல, யமனுடையவனல்ல, வருணனுடையவனல்ல; குபேரனுடன் எனக்கு நட்பில்லை; விஷ்ணுவால் நான் அனுப்பப்படவில்லை.',
        '0.13': '“இதுவே என் இனம்: நான் வானரன், இங்கே வந்தேன். அரக்கர் அரசனைக் காண்பது எனக்கு அரிதாக இருந்தது;',
        '0.14': '“ஆகவே அரக்கர் அரசனைக் காண்பதற்காகவே அவனுடைய சோலையை அழித்தேன். அப்போது போரை விரும்பிய அந்த வலிய அரக்கர்கள் வந்தனர்,',
        '0.15': '“என் உடலைக் காப்பதற்காகப் போரில் நான் அவர்களை எதிர்த்துப் போரிட்டேன். தேவர் அசுரர்களும் அஸ்திரப் பாசங்களால் என்னைக் கட்ட முடியாது;',
        '0.16': '“ஏனெனில் இந்த வரமும் பிதாமகனிடமிருந்து எனக்குக் கிடைத்துள்ளது. அரசனைக் காணும் விருப்பத்தால் நான் அஸ்திரத்துக்குக் கட்டுப்பட்டேன்.',
        '0.17': '“அஸ்திரத்திலிருந்து விடுபட்டிருந்தும் அரக்கர்கள் என்னை உன் முன் கொண்டுவந்தனர். ராமனின் ஒரு காரியத்துக்காக நான் உன்னிடம் வந்திருக்கிறேன்.',
        '0.18': '“அளவற்ற ஒளியுடைய ராகவனின் தூதன் நான் என்று அறிந்து, பிரபுவே, உனக்கு நன்மை தரும் என் இந்தச் சொற்களைக் கேள்.”',
        '0.19': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் ஐம்பதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-51': {
      verses: {
        '0.0': 'அந்தப் பெரும் வலியனை நோக்கி, துணிவுடைய வானர சிரேஷ்டன் அமைதியாகப் பத்துத்தலையனிடம் பொருள்நிறைந்த சொற்களைக் கூறினான்:',
        '0.1': '“சுக்ரீவனின் செய்தியுடன் நான் இங்கே உன்னிடம் வந்திருக்கிறேன். அரக்கர் தலைவனே, உன் சகோதரனான வானர அரசன் உன் நலத்தை விசாரித்தான்.',
        '0.2': '“உன் சகோதரனான மகாத்மா சுக்ரீவனின் செய்தியைக் கேள் — அறமும் பொருளும் கூடிய, இம்மைக்கும் மறுமைக்கும் நன்மை தரும் சொல்.',
        '0.3': '“தேர்கள், யானைகள், குதிரைகள் நிறைந்த, உலகுக்குத் தந்தை போன்ற உறவினனான, தேவேந்திரனுக்கு நிகரான ஒளியுடைய தசரதன் என்ற அரசன் இருந்தான்.',
        '0.4': '“அவனுடைய மூத்த மகன் நீண்ட கைகளுடையவன், மிகவும் அன்புக்குரியவன், தலைவன்; தந்தையின் கட்டளைப்படி வீட்டை விட்டுத் தண்டகாரண்யத்தில் நுழைந்தான் —',
        '0.5': '“சகோதரன் லக்ஷ்மணனுடனும் மனைவி சீதையுடனும் — அறவழியைப் பற்றிய, மிகுந்த ஒளியுடைய ராமன் என்பவன்.',
        '0.6': '“விதேக அரசன் மகாத்மா ஜனகனின் மகளான, சீதை என்று புகழ்பெற்ற அவனுடைய மனைவி ஜனஸ்தானத்தில் காணாமல் போனாள்.',
        '0.7': '“அந்தத் தேவியைத் தேடியவாறு அரசகுமாரன் தம்பியுடன் ரிஷ்யமூகத்துக்கு வந்து சுக்ரீவனைச் சந்தித்தான்.',
        '0.8': '“சுக்ரீவன் அவனுக்குச் சீதையைத் தேடுவதாக வாக்களித்தான்; ராமனும் சுக்ரீவனுக்கு வானர ராஜ்யத்தைத் தருவதாக வாக்களித்தான்.',
        '0.9': '“பின்னர் அந்த அரசகுமாரன் போரில் வாலியைக் கொன்று, சுக்ரீவனை வானரர் கரடிகளின் கணங்களுக்குத் தலைவனாக அரசில் அமர்த்தினான்.',
        '0.10': '“வானர சிரேஷ்டனான வாலியை நீ முன்பே அறிவாய்; அந்த வானரன் போரில் அவனுடைய ஒரே அம்பால் கொல்லப்பட்டான்.',
        '0.11': '“சீதையைத் தேடுவதில் ஆர்வமுள்ள, சொல் தவறாத வானர அரசன் சுக்ரீவன் எல்லாத் திசைகளுக்கும் வானரர்களை அனுப்பியிருக்கிறான்.',
        '0.12': '“ஆயிரக்கணக்கான, லட்சக்கணக்கான, கோடிக்கணக்கான வானரர்கள் எல்லாத் திசைகளிலும், கீழேயும் மேலே வானிலும் அவளைத் தேடுகின்றனர்.',
        '0.13': '“சிலர் கருடனுக்கு நிகரானவர், சிலர் காற்றுக்கு நிகரானவர் — தடையற்ற செலவும் விரைவும் பெரும் வலிமையும் உடைய வானர வீரர்கள்.',
        '0.14': '“நான் ஹனுமான் எனும் வாயுவின் சொந்த மகன். சீதைக்காக நூறு யோஜனை அகலமுடைய கடலை விரைவாக',
        '0.15': '“தாண்டி உன்னைக் காண விரும்பி இங்கே வந்திருக்கிறேன். திரிந்தபோது உன் இல்லத்தில் ஜானகியை நான் கண்டேன்.',
        '0.16': '“நீ அறத்தையும் பொருளையும் அறிந்தவன், தவத்தால் பலவற்றைப் பெற்றவன்; ஆகவே பேரறிவாளனே, பிறன் மனைவியை நீ சிறைவைக்கக் கூடாது.',
        '0.17': '“ஏனெனில் உன்னைப் போன்ற அறிவாளிகள் அறத்துக்கு முரணான, பல ஆபத்துகள் நிறைந்த, வேரையே அழிக்கும் செயல்களில் ஈடுபட மாட்டார்கள்.',
        '0.18': '“லக்ஷ்மணன் எய்யும், ராமனின் சினத்தைப் பின்தொடரும் அம்புகளின் முன் தேவர் அசுரர்களிலும் யார் நிற்க முடியும்?',
        '0.19': '“அரசே, ராகவனுக்குத் தீங்கு செய்துவிட்டு இன்பம் பெறக்கூடியவன் மூவுலகிலும் எவனும் இல்லை.',
        '0.20': '“ஆகவே முக்காலத்துக்கும் நன்மை தரும், அறத்துக்கு உகந்த, பொருளுக்கு ஏற்ற இந்தச் சொல்லை ஏற்றுக்கொள்: ஜானகியை மன்னனிடம் திருப்பிக் கொடு.',
        '0.21': '“நான் இந்தத் தேவியைக் கண்டுவிட்டேன்; இங்கே அரிதானதைப் பெற்றுவிட்டேன். எஞ்சிய அடுத்த காரியத்தை ராகவனே செய்வான்.',
        '0.22': '“துயரில் ஆழ்ந்த சீதையை நான் இங்கே கண்டேன் — உன் இல்லத்தில் இருக்கும் அவளை ஐந்து தலை நாகம் என்று நீ அறியவில்லை.',
        '0.23': '“மிகுதியாக நஞ்சு கலந்த உணவை வலிமையாலும் செரிக்க முடியாதது போல், இவளைத் தேவர் அசுரர்களாலும் செரிக்க முடியாது.',
        '0.24': '“தவத்தின் வெம்மையால் நீ பெற்ற இந்த அறச்செல்வம் உன் உயிர்க்காப்பே; அதை அழிப்பது முறையல்ல.',
        '0.25': '“தவத்தால் தேவர் அசுரர்களிடமிருந்து உனக்குக் கிடைத்ததாக நீ கருதும் கொல்லப்படாமையிலும் ஒரு பெரிய காரணம் (குறை) உள்ளது:',
        '0.26': '“சுக்ரீவன் தேவனுமல்ல, யக்ஷனுமல்ல, அரக்கனுமல்ல; அரசே, ராகவன் மனிதன், சுக்ரீவன் வானர அரசன். அப்படியிருக்க அரசே, உன் உயிரை எப்படிக் காப்பாய்?',
        '0.27': '“சேர்த்த அறம் அதர்மத்தின் பலனை அழிப்பதில்லை; அந்தப் பலன் தவறாமல் பின்தொடரும்; அதர்மத்தை அழிப்பது அறம் ஒன்றே.',
        '0.28': '“அறத்தின் பலனை நீ ஏற்கெனவே பெற்றுவிட்டாய், ஐயமில்லை; இந்த அதர்மத்தின் பலனையும் விரைவில் அடைவாய்.',
        '0.29': '“ஜனஸ்தானப் படுகொலையையும் வாலியின் வதத்தையும் ராம சுக்ரீவரின் நட்பையும் அறிந்து, உனக்கு நன்மையானதை உணர்ந்துகொள்.',
        '0.30': '“உண்மையில் நான் ஒருவனே குதிரைகள், தேர்கள், யானைகளுடன் லங்கையை அழிக்க வல்லவன்; ஆனால் அது அவனுடைய (ராமனுடைய) முடிவல்ல.',
        '0.31': '“ஏனெனில் சீதையை அவமதித்த பகைவர்களை அழிப்பதாக ராமன் வானரர் கரடிகளின் கணங்களின் முன்னிலையில் சபதம் செய்திருக்கிறான்.',
        '0.32': '“ராமனுக்குத் தீங்கு செய்தால் சாக்ஷாத் இந்திரனும் இன்பம் பெற மாட்டான்; உன்னைப் போன்றவனைப் பற்றிச் சொல்லவும் வேண்டுமா?',
        '0.33': '“சீதை என்று நீ அறியும், உன் இல்லத்தில் இருக்கும் இவளை, லங்கை முழுவதையும் அழிக்கும் காளராத்திரி என்று அறி.',
        '0.34': '“சீதையின் உருவில் நீயே உன் தோளில் மாட்டிக்கொண்ட இந்தக் காலபாசம் போதும்; உன் நலனைப் பற்றி எண்ணு.',
        '0.35': '“சீதையின் ஒளியால் எரிந்த, ராமனின் சினத்தால் மூட்டப்பட்ட, மாடங்களும் தெருக்களும் கொண்ட இந்த நகரம் எரிவதைப் பார்!',
        '0.36': '“உன் நண்பர்கள், அமைச்சர்கள், உறவினர்கள், சகோதரர்கள், மக்கள், நலம் விரும்பிகள், இன்பங்கள், மனைவியர், லங்கை ஆகியவற்றை அழிவுக்கு இட்டுச் செல்லாதே.',
        '0.37': '“அரக்கர் அரசர்க்கு அரசனே, என் உண்மையான சொல்லைக் கேள் — வானரனும் தூதனும் சிறப்பாக ராமனின் அடியவனுமான என் சொல்.',
        '0.38': '“பெரும் புகழுடைய ராமன் அசையும் அசையாப் பொருள்களுடன் எல்லா உலகங்களையும் அழித்து மீண்டும் அப்படியே படைக்க வல்லவன்.',
        '0.39': '“தேவர், அசுரர், மன்னர்களிடையிலும், யக்ஷர், அரக்கர், பாம்புகளிடையிலும், வித்யாதரர், நாகர், கந்தர்வர், விலங்குகளிடையிலும்,',
        '0.40': '“சித்தர், கின்னர அரசர், பறவைகளிடையிலும் — எங்கும், எல்லா உயிர்களிடையிலும், எக்காலத்திலும் அத்தகையவன் எவனும் இல்லை',
        '0.41': '“விஷ்ணுவுக்கு நிகரான வீரமுடைய ராமனை எதிர்த்துப் போரிடக் கூடியவன். எல்லா உலகங்களுக்கும் தலைவனும் அரசர்களில் சிங்கமுமான ராமனுக்கு இத்தகைய தீங்கைச் செய்த உனக்கு உயிர் பிழைப்பது அரிது.',
        '0.42': '“இரவுலாவிகளின் தலைவனே, தேவர், தைத்தியர், கந்தர்வர், வித்யாதரர், நாகர், யக்ஷர் — எவரும் மூவுலகத் தலைவனான ராமனின் முன் போரில் நிற்க முடியாது.',
        '0.43': '“சுயம்புவான நான்முகன் பிரம்மனோ, திரிபுரத்தை அழித்த முக்கண் ருத்ரனோ, தேவர் தலைவனான மகேந்திரனோ போரில் ராகவனின் முன் நிற்க முடியாது.”',
        '0.44': 'நயமாகவும் தளர்வின்றியும் பேசிய கபியின் விரும்பாத சொற்களைக் கேட்டு, நிகரற்ற பத்துத்தலையன் சினத்தால் கண்களைச் சுழற்றி அந்த மகாகபியைக் கொல்லக் கட்டளையிட்டான்.',
        '0.45': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் ஐம்பத்தொன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-52': {
      verses: {
        '0.0': 'மகாத்மாவான அந்த வானரனின் சொற்களைக் கேட்டு, சினத்தால் தன்னிலை இழந்த ராவணன் அவனைக் கொல்லக் கட்டளையிட்டான்.',
        '0.1': 'தான் தூதன் என்று அறிவித்தவனைக் கொல்லத் தீயவனான ராவணன் கட்டளையிட்டபோது விபீஷணன் அதை ஏற்கவில்லை.',
        '0.2': 'அரக்கர் தலைவன் சினந்திருப்பதையும் அந்தச் செயல் நெருங்கியிருப்பதையும் அறிந்து, கடமையில் நிலைத்த விபீஷணன் செய்ய வேண்டியதைச் சிந்தித்தான்.',
        '0.3': 'முடிவுக்கு வந்தபின், சொல்வன்மை மிக்க அவன், மதிப்புக்குரிய, பகைவரை வென்ற தன் அண்ணனிடம் இனிமையாக மிகவும் நன்மை தரும் சொற்களைக் கூறினான்:',
        '0.4': '“அரக்கர் அரசனே, பொறுத்துக்கொள், சினத்தை விடு; அருள்கூர்ந்து என் இந்தச் சொல்லைக் கேள். நன்மை தீமை அறிந்த நல்ல அரசர்கள் தூதனைக் கொல்வதில்லை.',
        '0.5': '“அரசே, வீரனே, இந்தக் கபியைக் கொல்வது அறத்துக்கு முரணானது, உலக வழக்கில் பழிக்கப்படுவது, உனக்குத் தகாதது.',
        '0.6': '“நீ அறம் அறிந்தவன், நன்றியுடையவன், அரசநெறியில் தேர்ந்தவன், உயிர்களின் உயர்வு தாழ்வு அறிந்தவன்; பரமார்த்தத்தை அறிந்தவன் நீயே.',
        '0.7': '“உன்னைப் போன்ற அறிவாளிகளும் சினத்துக்கு ஆட்பட்டால், சாஸ்திரப் புலமை வெறும் உழைப்பே.',
        '0.8': '“ஆகவே பகைவரை அழிப்பவனே, நெருங்க முடியாத அரக்கர் அரசனே, அருள்கூர்; தக்கது தகாதது என்று தீர்மானித்து, தூதனுக்கு ஏற்ற தண்டனையை விதி.”',
        '0.9': 'விபீஷணனின் சொற்களைக் கேட்டு, பெருஞ்சினம் கொண்ட அரக்கர் தலைவன் ராவணன் மறுமொழி கூறினான்:',
        '0.10': '“பகைவரை அழிப்பவனே, பாவிகளைக் கொல்வதில் பாவம் இல்லை; ஆகவே பாவம் செய்த இந்த வானரனை நான் கொல்வேன்.”',
        '0.11': 'அதர்மத்தை வேராகக் கொண்ட, பல குறைகள் நிறைந்த, இழிந்தோர்க்கு உரிய சொல்லைக் கேட்டு, அறிவாளிகளில் சிறந்த விபீஷணன் உயர்ந்த உண்மைச் சொல்லைக் கூறினான்:',
        '0.12': '“லங்கேஸ்வரனே, அரக்கர் அரசனே, அருள்கூர்; அறம் பொருள் ஆகியவற்றின் நுட்பமுடைய சொல்லைக் கேள். அரசே, எல்லாச் சூழல்களிலும் எல்லா இடங்களிலும் தூதர்கள் கொல்லப்படக் கூடாது என்று சான்றோர் கூறுகின்றனர்.',
        '0.13': '“இந்தப் பகைவன் எல்லை மீறியவன், அளவற்ற தீங்கு செய்திருக்கிறான், ஐயமில்லை; இருப்பினும் சான்றோர் தூதனைக் கொல்வதை ஏற்பதில்லை — தூதனுக்குப் பல வேறு தண்டனைகள் அறியப்பட்டுள்ளன.',
        '0.14': '“உறுப்புகளைச் சிதைத்தல், சாட்டையால் அடித்தல், மொட்டையடித்தல், அடையாளக் குறி இடுதல் — இவையே தூதனுக்குச் சொல்லப்பட்ட தண்டனைகள்; தூதனைக் கொல்வதை நாம் கேட்டதே இல்லை.',
        '0.15': '“அறத்திலும் பொருளிலும் பயிற்சி பெற்ற அறிவுடைய, உயர்வு தாழ்வு அறிந்து முடிவு செய்யும் உன்னைப் போன்றவன் சினத்துக்கு எப்படி ஆட்படலாம்? மன உறுதி உடையவர்கள் சினம் கொள்வதில்லை.',
        '0.16': '“வீரனே, அறவாதத்திலோ உலக நடைமுறையிலோ சாஸ்திர அறிவைப் பெறுவதிலோ உனக்கு நிகரானவர் எவரும் இல்லை; நீ எல்லாத் தேவர் அசுரர்களிலும் சிறந்தவன்.',
        '0.17': '“வீரமும் ஊக்கமும் மனவலிமையும் உடைய தேவர் அசுரர்களாலும் வெல்ல முடியாத, அளவிட முடியாத நீ, போர்களில் பலமுறை தேவர் கூட்டங்களையும் மன்னர்களையும் வென்றிருக்கிறாய்.',
        '0.18': '“தேவர் தைத்தியர்களின் பகைவனும் சூரனும் வீரனும் வெல்லப்படாதவனுமான உன்னைப் போன்றவனுக்கு மனத்தாலும் தீங்கு நினைக்கும் வீரர்கள் அதற்கு முன்பே உயிரிழக்கின்றனர்.',
        '0.19': '“இந்தக் கபியைக் கொல்வதில் எந்த நன்மையையும் நான் காணவில்லை; இந்தக் கபியை அனுப்பியவர்கள் மீதே இந்தத் தண்டனை விழட்டும்.',
        '0.20': '“நல்லவனோ கெட்டவனோ, இவனைப் பிறர் அனுப்பியுள்ளனர்; பிறர் சார்பில் பேசும், பிறருக்குக் கட்டுப்பட்ட தூதன் கொல்லப்படத் தகுந்தவனல்ல.',
        '0.21': '“மேலும் அரசே, இவன் கொல்லப்பட்டால், பெருங்கடலின் அக்கரையிலிருந்து மீண்டும் இங்கே வரக்கூடிய வேறொரு வான்வழிச் செல்வோனை நான் காணவில்லை.',
        '0.22': '“ஆகவே பகைவர் நகரங்களை வெல்பவனே, இவனைக் கொல்ல முயலாதே; இந்திரனுடன் கூடிய தேவர்கள் மீது நீ உன் முயற்சியைச் செலுத்த வேண்டும்.',
        '0.23': '“போரை விரும்புபவனே, இவன் அழிந்தால், உனக்கு எதிரான அந்த இரு அடங்காத அரசகுமாரர்களைப் போருக்குத் தூண்டக்கூடிய வேறு உயிரை நான் காணவில்லை.',
        '0.24': '“அரக்கர்களின் மனத்துக்கு மகிழ்ச்சி தருபவனே, வீரமும் ஊக்கமும் உடைய தேவர் அசுரர்களாலும் வெல்ல முடியாத நீ இந்தப் போர் வாய்ப்பை அழிப்பது தகாது.',
        '0.25': '“உனக்கு நலம் விரும்புபவர்களும், சூரர்களும், கட்டுப்பாடுடையவர்களும், பெருங்குணமுடைய குலங்களில் பிறந்தவர்களும், மனவலிமை மிக்கவர்களும், ஆயுதம் ஏந்துவோரில் சிறந்தவர்களும், சினத்துக்குப் புகழ்பெற்றவர்களும், நன்கு பேணப்பட்டவர்களுமான வீரர்கள் உள்ளனர்.',
        '0.26': '“ஆகவே உன் படையின் ஒரு பகுதியாகச் சிலர் உன் கட்டளைப்படி இன்றே சென்று, அந்த இரு மூட அரசகுமாரர்களைப் பிடித்து, பகைவரிடையே உன் ஆற்றலைக் காட்டட்டும்.”',
        '0.27': 'இரவுலாவிகளின் தலைவனும், தேவலோகத்தின் பகைவனும், பெருவலியனும், அரக்கர் அரசர்களில் முதன்மையானவனுமான ராவணன், தம்பி விபீஷணனின் சிறந்த இனிய சொல்லை அறிவால் ஏற்றுக்கொண்டான்.',
        '0.28': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் ஐம்பத்திரண்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-53': {
      verses: {
        '0.0': 'மகாத்மாவான தம்பியின் இடத்துக்கும் காலத்துக்கும் ஏற்ற அந்தச் சொற்களைக் கேட்டு பத்துக்கழுத்தன் மறுமொழி கூறினான்:',
        '0.1': '“நீ சரியாகச் சொன்னாய்: தூதனைக் கொல்வது பழிக்கப்படுவது. ஆனால் கொலையல்லாத வேறொரு தண்டனை இவனுக்கு நிச்சயம் கொடுக்கப்பட வேண்டும்.',
        '0.2': '“குரங்குகளுக்கு வாலே விருப்பமான அணிகலன் என்பர். ஆகவே இவனுடைய வாலுக்கு உடனே தீ வையுங்கள்; எரிந்த வாலுடன் இவன் போகட்டும்.',
        '0.3': '“பின்னர் உறுப்புச் சிதைவால் வாடிய பரிதாபமான இவனை இவனுடைய நண்பர்கள், சுற்றத்தார், உறவினர், நலம் விரும்பிகள் அனைவரும் பார்க்கட்டும்.”',
        '0.4': 'அரக்கர் அரசன் கட்டளையிட்டான்: “எரியும் வாலுடன் இவனை அரக்கர்கள் நகரம் முழுவதும் சந்திகள் தோறும் ஊர்வலமாகக் கொண்டு செல்லட்டும்.”',
        '0.5': 'அவனுடைய அந்தச் சொல்லைக் கேட்டு, சினத்தால் கடுமையான அரக்கர்கள் அவனுடைய வாலைப் பழைய பருத்தித் துணிகளால் சுற்றினர்.',
        '0.6': 'வால் சுற்றப்படும்போது அந்த மகாகபி, காட்டில் காய்ந்த விறகைப் பெற்ற நெருப்பைப் போல் வளர்ந்தான்.',
        '0.7': 'பின் எண்ணெய் ஊற்றி அவர்கள் அதில் தீ மூட்டினர்; எரியும் வாலால் அவன் அந்த அரக்கர்களை அடித்தான்.',
        '0.8': 'சினமும் பொறுமையின்மையும் நிறைந்த, இளஞ்சூரியன் போன்ற முகமுடைய அந்த வானர சிரேஷ்டனை, ஒன்றுகூடிய கொடிய அரக்கர்கள் மீண்டும் பிடித்தனர்.',
        '0.9': 'பெண்கள், குழந்தைகள், முதியோருடன் இரவுலாவிகள் மகிழ்ந்தனர்; கட்டுண்ட அந்த வீரன் அந்நேரத்துக்கு ஏற்ற முடிவை எடுத்தான்.',
        '0.10': '“கட்டுண்டிருந்தாலும் அரக்கர்கள் எனக்கு ஈடல்லர்; இந்தப் பாசங்களை அறுத்து மேலே தாவி இவர்களை மீண்டும் கொல்ல முடியும்.',
        '0.11': '“தலைவனின் கட்டளைப்படி தலைவனின் நன்மைக்காகத் திரியும் என்னை இந்தத் தீயவர்கள் கட்டுகின்றனர்; இருந்தும் நான் செய்ததற்கு இவர்களால் பழிதீர்க்க முடியவில்லை.',
        '0.12': '“போரில் அரக்கர் அனைவருக்கும் நான் ஒருவனே போதும்; ஆனால் ராமனின் மகிழ்ச்சிக்காக நான் இதையும் பொறுத்துக்கொள்வேன்.',
        '0.13': '“லங்கையை நான் மீண்டும் ஒருமுறை சுற்றிப் பார்க்க வேண்டும்; இரவில் இதன் அரண்களின் அமைப்பை நான் சரியாகப் பார்க்கவில்லை.',
        '0.14': '“பகலில் லங்கையை நான் நிச்சயம் பார்க்க வேண்டும். இவர்கள் விரும்பியபடி என்னை மீண்டும் கட்டட்டும், வாலுக்குத் தீ வைக்கட்டும்;',
        '0.15': '“அரக்கர்கள் துன்புறுத்தினாலும் என் மனத்துக்குச் சோர்வில்லை.” அப்போது அந்த அரக்கர்கள், தன் எண்ணத்தை மறைத்திருந்த வலிய மகாகபியை,',
        '0.16': 'அந்த வானர யானையை மகிழ்ச்சியுடன் பற்றி, சங்கு பேரிகை முழக்கங்களுடன் அவனுடைய செயல்களை அறிவித்தவாறு அழைத்துச் சென்றனர்.',
        '0.17': 'கொடுஞ்செயல் புரியும் அரக்கர்கள் அவனை அந்த நகரில் ஊர்வலமாகக் கொண்டு சென்றனர்; அரக்கர்கள் பின்தொடர, பகைவரை அடக்குபவன் இன்பமாகச் சென்றான்.',
        '0.18': 'இவ்வாறு ஹனுமான் அரக்கர்களின் பெருநகரைச் சுற்றினான்; அந்த மகாகபி விசித்திரமான விமானங்களை (மாளிகைகளை) கண்டான்,',
        '0.19': 'சுற்றுச்சுவர் சூழ்ந்த நிலப்பகுதிகளையும், நன்கு பிரிக்கப்பட்ட சதுக்கங்களையும், வீடுகள் நெருங்கிய தெருக்களையும், நாற்சந்திகளையும் கண்டான்;',
        '0.20': 'அவ்வாறே முக்கியத் தெருக்களையும் சந்துகளையும் வீடுகளுக்கு இடையிலான இடங்களையும் கண்டான்; சதுக்கங்களிலும் சந்திகளிலும் ராஜவீதியிலும்',
        '0.21': 'அரக்கர் அனைவரும் அந்தக் கபியை ஒற்றன் என்று அறிவித்தனர். பெண்கள், குழந்தைகள், முதியோர் ஆர்வத்துடன் ஆங்காங்கே வெளியே வந்தனர்,',
        '0.22': 'எரியும் வாலுடைய ஹனுமானைக் காணும் ஆவலுடன். ஹனுமானின் வால் நுனி எரிந்துகொண்டிருந்தபோது,',
        '0.23': 'அந்த விகாரக் கண்களுடைய அரக்கியர் தேவியிடம் அந்த விரும்பாத செய்தியைச் சொன்னார்கள்: “சீதையே, உன்னுடன் பேசிய அந்தச் செம்முகக் கபி,',
        '0.24': '“எரியும் வாலுடன் ஊர்வலமாகக் கொண்டு செல்லப்படுகிறான்.” தன்னைக் கவர்ந்ததற்கு ஒப்பான அந்தக் கொடிய சொல்லைக் கேட்டு,',
        '0.25': 'துயரால் வாடிய வைதேஹி அக்னியை நோக்கித் திரும்பினாள்; அப்போது அவள் அந்த மகாகபியின் நலனையே விரும்பினாள்.',
        '0.26': 'அகன்ற கண்களுடைய அவள் தூய மனத்துடன் அவி சுமக்கும் அக்னியை வேண்டினாள்: “நான் கணவனுக்குப் பணிவிடை செய்திருந்தால், தவம் புரிந்திருந்தால், ஒருவனுக்கே மனைவியாக இருந்திருந்தால், ஹனுமானுக்குக் குளிர்ச்சியாக இரு.',
        '0.27': '“அந்த அறிவாளிக்கு (ராமனுக்கு) என்மேல் சிறிதேனும் இரக்கம் இருந்தால், அல்லது என் நற்பேறு இன்னும் எஞ்சியிருந்தால், ஹனுமானுக்குக் குளிர்ச்சியாக இரு.',
        '0.28': '“அந்த அறவோன் என்னை நல்லொழுக்கமுடையவள் என்றும், அவனைச் சேர ஏங்குபவள் என்றும் அறிந்திருந்தால், ஹனுமானுக்குக் குளிர்ச்சியாக இரு.',
        '0.29': '“சொல் தவறாத உத்தம சுக்ரீவன் இந்தத் துயரக் கடலிலிருந்து என்னைக் கரையேற்றுவான் என்றால், ஹனுமானுக்குக் குளிர்ச்சியாக இரு.”',
        '0.30': 'அப்போது கூர்மையான சுடருடைய நெருப்பு அமைதியாக, வலப்புறம் சுழலும் கொழுந்துடன், மான்குட்டிக் கண்ணாளுக்குக் கபியின் நலத்தை அறிவிப்பது போல் எரிந்தது.',
        '0.31': 'ஹனுமானின் தந்தையான வாயுவும் வால் நெருப்புடன் கூடி, பனிக்காற்றைப் போல் குளிர்ந்து, தேவிக்கு ஆறுதல் தந்தவாறு வீசினான்.',
        '0.32': 'வால் எரியும்போது வானரன் எண்ணினான்: “எரியும் இந்த நெருப்பு ஏன் என்னை எங்குமே சுடவில்லை?',
        '0.33': '“பெரும் சுடர்கள் தெரிகின்றன, இருந்தும் எனக்கு வலி இல்லை; வால் நுனியில் பனிப்பொழிவு தங்கியிருப்பது போல் இருக்கிறது.',
        '0.34': '“அல்லது இது தெளிவு — நான் தாவும்போது கண்டது போல், ராமனின் ஆற்றலால் கடலில் மலை (மைனாகம்) வியப்பாக எழுந்தது.',
        '0.35': '“ராமனுக்காகக் கடலுக்கும் அறிவுடைய மைனாகனுக்கும் அத்தகைய பரபரப்பு இருந்ததென்றால், அக்னி என்ன செய்ய மாட்டான்?',
        '0.36': '“சீதையின் கருணையாலும், ராகவனின் ஒளியாலும், என் தந்தையின் நட்பாலும் நெருப்பு என்னைச் சுடவில்லை.”',
        '0.37': 'அந்த வானர யானை மீண்டும் கணநேரம் எண்ணியது: “என்னைப் போன்றவனை இங்கே இந்த இழிந்த அரக்கர்கள் கட்டுவதா?',
        '0.38': '“எனக்கு வீரம் இருக்கும்போது இதற்குப் பதிலடி கொடுப்பதே தகும்.” பின் அந்தப் பாசங்களை அறுத்து, வேகமுடைய அந்த மகாகபி',
        '0.39': 'வேகமாக மேலே தாவி முழங்கினான். பின் பொலிவுடைய வாயுபுத்திரன் மலைச்சிகரம் போல் உயர்ந்த நகர வாயிலை அடைந்தான்,',
        '0.40': 'அங்கே அரக்கர் கூட்டம் கலைந்திருந்தது. மலையளவு பெரியவனாகியிருந்த அந்தத் தன்னடக்கமுடையவன் கணப்பொழுதில் மீண்டும்',
        '0.41': 'மிகச் சிறியவனாகிக் கட்டுகளை உதிர்த்தான்; விடுபட்ட அந்தப் பொலிவுடையவன் மீண்டும் மலைபோல் ஆனான்.',
        '0.42': 'சுற்றிலும் பார்த்தபோது தோரணத்தில் சார்த்தியிருந்த பரிகத்தைக் கண்டான்; இரும்புப் பூண் கட்டிய அந்தப் பரிகத்தைப் பற்றி, நீண்ட கைகளுடைய மாருதி அந்தக் காவலர்கள் அனைவரையும் மீண்டும் கொன்றான்.',
        '0.43': 'அவர்களைக் கொன்று, போரில் கடும் வீரமுடைய அவன், எரியும் வாலின் சுடர்மாலையால் கதிர்மாலைச் சூரியனைப் போல் ஒளிர்ந்தவாறு மீண்டும் லங்கையை நோக்கினான்.',
        '0.44': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் ஐம்பத்துமூன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-54': {
      verses: {
        '0.0': 'பின்னர் லங்கையை நோக்கியவாறு, விருப்பம் நிறைவேறி ஊக்கம் பெருகிய அந்தக் கபி எஞ்சிய காரியத்தைப் பற்றிச் சிந்தித்தான்.',
        '0.1': '“இந்த அரக்கர்களுக்கு மேலும் துன்பம் உண்டாக்கும் எந்தச் செயல் இப்போது இங்கே எனக்கு எஞ்சியுள்ளது?',
        '0.2': '“சோலையை அழித்தாயிற்று, முக்கிய அரக்கர்களைக் கொன்றாயிற்று, படையின் ஒரு பகுதியை அழித்தாயிற்று; எஞ்சியிருப்பது அரணை அழிப்பதே.',
        '0.3': '“அரண் அழிந்தால் அடுத்த காரியம் எளிதாகும்; இந்தச் செயலில் சிறிது முயற்சியால் என் உழைப்பு பயனடையும்.',
        '0.4': '“என் வாலில் எரியும் இந்த அக்னியை இந்தச் சிறந்த மாளிகைகளால் திருப்திப்படுத்துவதே முறை.”',
        '0.5': 'அப்போது எரியும் வாலுடன், மின்னலுடைய மேகம் போல், அந்த மகாகபி லங்கையின் மாளிகைகளின் உச்சிகளில் உலவினான்.',
        '0.6': 'அரக்கர்களின் ஒரு வீட்டிலிருந்து மற்றொரு வீட்டுக்கு, தோட்டங்களுக்கும் மாளிகைகளுக்கும், அந்த வானரன் அச்சமின்றிப் பார்த்தவாறு திரிந்தான்.',
        '0.7': 'பெரும் வேகத்துடன் பிரஹஸ்தனின் மாளிகையின் மேல் குதித்து, காற்றுக்கு நிகரான அந்த வலியவன் அங்கே தீ வைத்தான்,',
        '0.8': 'பின்னர் வலிய ஹனுமான் மகாபார்ஸ்வனின் மற்றொரு மாளிகைக்குத் தாவி, ஊழித்தீயின் சுடர் போன்ற நெருப்பை விட்டான்.',
        '0.9': 'அவ்வாறே மிகுந்த ஒளியுடைய அந்த மகாகபி வஜ்ரதம்ஷ்டிரன், சுகன், அறிவுடைய சாரணன் ஆகியோரின் மாளிகைகளின் மேல் தாவினான்.',
        '0.10': 'பின்னர் அந்த வானரப் படைத்தலைவன் இந்திரஜித்தின் மாளிகையை எரித்தான்; அதன்பின் ஜம்புமாலி, சுமாலி ஆகியோரின் மாளிகைகளை எரித்தான்,',
        '0.11': 'ரஸ்மிகேது, சூரியசத்ரு, ஹ்ரஸ்வகர்ணன், தம்ஷ்டிரன், அரக்கன் ரோமசன் ஆகியோரின் மாளிகைகளையும்,',
        '0.12': 'யுத்தோன்மத்தன், மத்தன், அரக்கன் த்வஜக்ரீவன், கொடிய வித்யுஜ்ஜிஹ்வன், ஹஸ்திமுகன் ஆகியோரின் மாளிகைகளையும்,',
        '0.13': 'கராளன், விசாலன், சோணிதாக்ஷன் ஆகியோரின் மாளிகைகளையும், கும்பகர்ணனின் மாளிகையையும், மகராக்ஷனின் மாளிகையையும்,',
        '0.14': 'நராந்தகன், கும்பன், தீயவனான நிகும்பன் ஆகியோரின் மாளிகைகளையும், யக்ஞசத்ரு, பிரம்மசத்ரு ஆகியோரின் மாளிகைகளையும் —',
        '0.15': 'விபீஷணனின் வீட்டை மட்டும் விட்டு, மிகுந்த ஒளியுடைய அந்த வானர சிரேஷ்டன் முறையாகச் சென்று ஒவ்வொன்றாக எரித்தான்.',
        '0.16': 'அந்த விலையுயர்ந்த மாளிகைகளில் பெரும் புகழுடைய அந்த வானர யானை செல்வந்தர்களின் வீடுகளின் செல்வத்தை எரித்தது.',
        '0.17': 'அவை அனைத்தையும் கடந்து, வலியவனும் பொலிவுடையவனுமான அவன் பின்னர் அரக்கர் அரசன் ராவணனின் மாளிகையை அடைந்தான்.',
        '0.18': 'பின்னர் பலவகை ரத்தினங்களால் அலங்கரிக்கப்பட்ட, மேரு மந்தரம் போன்ற, பல மங்கலப் பொருள்களால் விளங்கிய அந்த முதன்மை மாளிகையின் மேல்,',
        '0.19': 'வீர ஹனுமான் வால் நுனியில் இருந்த எரியும் நெருப்பை விட்டு, ஊழிக்கால மேகம் போல் முழங்கினான்.',
        '0.20': 'காற்றின் சேர்க்கையால் மிக வேகமான வலிமைமிக்க நெருப்பு காலத்தீயைப் போல் கொழுந்துவிட்டுப் பரவியது.',
        '0.21': 'காற்று எரியும் நெருப்பை அந்த வீடுகளில் எல்லாம் பரப்பியது; பொன்வலைகளும் முத்துக்களும் மணிகளும் கொண்ட,',
        '0.22': 'ரத்தினங்கள் நிறைந்த பெரிய மாளிகைகள் சரிந்தன; உச்சிகள் உடைந்து அவை தரையில் விழுந்தன,',
        '0.23': 'புண்ணியம் தீர்ந்தபோது வானிலிருந்து விழும் சித்தர்களின் விமானங்களைப் போல. ஓடித் திரிந்த அரக்கர்களின் பேரிரைச்சல் எழுந்தது,',
        '0.24': 'ஊக்கம் உடைந்து பொலிவு இழந்து தங்கள் தங்கள் வீடுகளைக் காக்க முயன்ற அவர்கள்: “ஐயோ, இவன் நிச்சயம் குரங்கு உருவில் வந்த அக்னியே!” என்றனர்.',
        '0.25': 'பால்குடிக்கும் குழந்தைகளை ஏந்திய பெண்கள் அழுதவாறு திடீரென விழுந்தனர்; சிலர் நெருப்பு சூழ்ந்த உறுப்புகளுடனும் அவிழ்ந்த கூந்தலுடனும் மாடங்களிலிருந்து விழுந்தனர்,',
        '0.26': 'விழுந்தவர்கள் வானின் மேகங்களிலிருந்து விழும் மின்னல்களைப் போல் ஒளிர்ந்தனர். வைரம், பவளம், வைடூரியம், முத்து, வெள்ளி கலந்த',
        '0.27': 'விசித்திர உலோகங்கள் மாளிகைகளிலிருந்து உருகி ஓடுவதை அவன் கண்டான். நெருப்பு விறகாலும் புல்லாலும் ஒருபோதும் திருப்தியடையாதது போல்,',
        '0.28': 'அவ்வாறே அரக்கர் தலைவர்களைக் கொல்வதில் ஹனுமான் சிறிதும் திருப்தியடையவில்லை; ஹனுமானால் கொல்லப்பட்ட அரக்கர்களால் பூமியும் திருப்தியடையவில்லை.',
        '0.29': 'ருத்ரன் திரிபுரத்தை எரித்தது போல், வேகமுடைய மகாத்மாவான வானரன் ஹனுமானால் அந்த லங்கை நகரம் எரிக்கப்பட்டது.',
        '0.30': 'அப்போது லங்கை நகரின் மலைச்சிகரத்தில், வேகமுடைய ஹனுமானால் மூட்டப்பட்ட கடும் ஆற்றலுடைய நெருப்பு தன் சுடர்வளையத்தைப் பரப்பி எரிந்து எழுந்தது.',
        '0.31': 'ஊழிக்காலத் தீயைப் போன்ற உருவமுடைய, காற்றுடன் கூடிய அந்த நெருப்பு வானைத் தொடும்படி வளர்ந்தது; புகையற்ற சுடர்கள் வீடுகளைப் பற்றின; அரக்கர்களின் உடல்களே நெய்யாக அதன் சுடர்களுக்கு ஆகுதியாயின.',
        '0.32': 'கோடி சூரியர்களைப் போல் ஒளிர்ந்த அந்தப் பெருநெருப்பு லங்கை முழுவதையும் சூழ்ந்து நின்று, இடிபோன்ற பல ஓசைகளுடன் அண்டத்தையே பிளப்பது போல் விளங்கியது.',
        '0.33': 'அங்கே மிகப் பெருகிய நெருப்பு கடுமையான ஒளியுடனும் முருக்கம்பூப் போன்ற கொழுந்துடனும் வானை எட்டியது; அணையும் சுடர்களின் புகைக் கோடுகள் கொண்ட மேகங்கள் நீலோத்பலம் போல் விளங்கின.',
        '0.34': '“இவன் வஜ்ராயுதம் ஏந்திய தேவர் தலைவன் மகேந்திரனோ, சாக்ஷாத் யமனோ, வருணனோ, வாயுவோ? ருத்ரனின் நெருப்போ, சூரியனோ, குபேரனோ, சந்திரனோ? இவன் வானரனல்ல — காலனே!',
        '0.35': '“அல்லது எல்லோர்க்கும் பிதாமகனும் உலகைப் படைத்தவனுமான நான்முகன் பிரம்மனின் சினமே அரக்கர்களை அழிக்க வானர உருவெடுத்து இங்கே வந்ததோ?',
        '0.36': '“அல்லது சிந்தனைக்கு எட்டாத, வெளிப்படாத, முடிவற்ற, ஒன்றேயான விஷ்ணுவின் பரம ஒளியே அரக்கர்களை அழிக்கத் தன் மாயையால் இப்போது குரங்கு உருவில் வந்ததோ?”',
        '0.37': 'உயிர்க்கூட்டங்கள், வீடுகள், மரங்களுடன் அந்த நகரம் திடீரென எரிந்ததைக் கண்டு, அங்கே கூடிய பல முக்கிய அரக்கர்கள் இவ்வாறு கூறினர்.',
        '0.38': 'அப்போது அரக்கர்கள், குதிரைகள், தேர்கள், யானைகள், பறவைக் கூட்டங்கள், விலங்குகள், மரங்களுடன் திடீரென எரிந்த லங்கை பரிதாபமாகப் பேரிரைச்சலுடன் அழுதது.',
        '0.39': '“ஐயோ அப்பா! ஐயோ மகனே! அன்பனே! நண்பனே! ஐயோ உயிர்த்தலைவனே, நம் புண்ணியமெல்லாம் அழிந்தது!” — இவ்வாறு பலவாறு கதறிய அரக்கர்கள் மிகப் பயங்கரமான ஓலம் எழுப்பினர்.',
        '0.40': 'நெருப்புச் சுடர்களால் சூழப்பட்டு, முக்கிய வீரர்கள் கொல்லப்பட்டு, வீரர்கள் பின்வாங்கிய லங்கை, ஹனுமானின் சின வலிமையால் அடக்கப்பட்டுச் சாபத்தால் தாக்கப்பட்டது போல் ஆனது.',
        '0.41': 'கலங்கிய, அஞ்சிய, வருந்திய அரக்கர்களுடைய, கொழுந்துவிட்டு எரியும் சுடர் நெருப்பால் குறிக்கப்பட்ட லங்கையை, பெருமனமுடைய ஹனுமான் சுயம்புவின் சினத்தால் தாக்கப்பட்ட பூமி போல் கண்டான்.',
        '0.42': 'சிறந்த மரங்கள் நிறைந்த சோலையை அழித்து, போரில் பெரும் அரக்கர்களைக் கொன்று, ரத்தினம் போன்ற மாளிகைகளின் மாலை அணிந்த அந்த நகரை எரித்து, வாயுபுத்திரனான கபி ஹனுமான் நின்றான்.',
        '0.43': 'அந்தப் பல அரக்கர்களைக் கொன்று, பல மரங்களுடைய அந்தச் சோலையை அழித்து, அரக்கர்களின் வீடுகளுக்குத் தீ வைத்து, அந்த மகாத்மா மனத்தால் ராமனிடம் சென்றான்.',
        '0.44': 'அப்போது தேவகணங்கள் அனைத்தும், வானர வீரர்களில் முதன்மையானவனும், பெருவலியனும், காற்றின் வேகமுடையவனும், பேரறிவாளனுமான சிறந்த வாயுபுத்திரனைப் போற்றின.',
        '0.45': 'எல்லாத் தேவர்களும், முனிவர் சிரேஷ்டர்களும், கந்தர்வர், வித்யாதரர், நாகர்களும், அங்கிருந்த எல்லா மாபெரும் உயிர்களும் ஒப்பற்ற பேரின்பம் அடைந்தனர்.',
        '0.46': 'சோலையை அழித்து, போரில் அரக்கர்களைக் கொன்று, பயங்கரமான லங்கை நகரை எரித்து, மிகுந்த ஒளியுடைய அந்த மகாகபி விளங்கினான்.',
        '0.47': 'சிறந்த மாளிகைச் சிகரத்தின் உச்சியில் நின்ற அந்த வானர அரசர்களில் சிங்கம், எரியும் வாலின் சுடர்மாலையால் கதிர்மாலைச் சூரியனைப் போல் விளங்கியது.',
        '0.48': 'லங்கை முழுவதையும் துன்புறுத்திய பின், வானர சிரேஷ்டனான அந்த மகாகபி தன் வால் நெருப்பைக் கடலில் அணைத்தான்.',
        '0.49': 'அப்போது கந்தர்வர்களுடன் தேவர்களும் சித்தர்களும் பரமரிஷிகளும் எரிந்த லங்கையைக் கண்டு மிகுந்த வியப்படைந்தனர்.',
        '0.50': 'வானர சிரேஷ்டனான மகாகபி ஹனுமானைக் கண்டு, அவனைக் காலத்தீ என்று எண்ணி, எல்லா உயிர்களும் நடுங்கின.',
        '0.51': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் ஐம்பத்துநான்காம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-55': {
      verses: {
        '0.0': 'எரிந்துகொண்டிருந்த, அஞ்சிய அரக்கர் கூட்டங்கள் நிறைந்த லங்கை நகரைப் பார்த்து, வானரன் ஹனுமான் சிந்திக்கலானான்.',
        '0.1': 'அவனுக்குப் பெரும் அச்சம் உண்டாயிற்று, தன்மீதே வெறுப்பு எழுந்தது: “லங்கையை எரித்து நான் என்ன செய்துவிட்டேன்!',
        '0.2': '“பொங்கி எழுந்த சினத்தை, எரியும் நெருப்பை நீரால் அணைப்பது போல் அறிவால் அடக்கும் மகாத்மாக்களே பேறுபெற்றவர்கள்.',
        '0.3': '“சினந்தவன் எந்தப் பாவத்தைச் செய்ய மாட்டான்? சினந்தவன் பெரியோரையும் கொல்லக்கூடும்; சினந்த மனிதன் கடுஞ்சொற்களால் நல்லோரையும் இகழக்கூடும்.',
        '0.4': '“சினம் கொண்டவனுக்குச் சொல்லத் தகுந்தது தகாதது எதுவென்று ஒருபோதும் தெரியாது; சினந்தவனுக்குச் செய்யக்கூடாத செயலோ சொல்லக்கூடாத சொல்லோ எங்கும் இல்லை.',
        '0.5': '“பாம்பு பழைய சட்டையை உரிப்பது போல், எழுந்த சினத்தைப் பொறுமையாலேயே விலக்குபவனே உண்மையான மனிதன் எனப்படுவான்.',
        '0.6': '“சீதையைப் பற்றி எண்ணாமல் தீ வைத்துத் தலைவனுக்குக் கேடு செய்த மிகத் தீய மதியனும் வெட்கமற்றவனும் பெரும்பாவியுமான எனக்கு ஐயோ!',
        '0.7': '“இந்த நகரம் முழுதும் எரிந்திருந்தால், உத்தமி ஜானகியும் நிச்சயம் எரிந்திருப்பாள்; அறியாமல் நான் தலைவனின் காரியத்தைக் கெடுத்துவிட்டேன்.',
        '0.8': '“எதற்காக இந்த முயற்சி தொடங்கப்பட்டதோ அந்தக் காரியத்தையே நான் கெடுத்தேன்; லங்கையை எரிக்கும்போது சீதையை நான் காக்கவில்லை.',
        '0.9': '“இந்தக் காரியம் கிட்டத்தட்ட முடிந்திருந்தது, ஐயமில்லை; ஆனால் சினத்துக்கு ஆட்பட்ட நான் அதன் வேரையே அழித்துவிட்டேன்.',
        '0.10': '“ஜானகி அழிந்தாள் என்பது தெளிவு; லங்கையில் எரியாத பகுதி எதுவும் தெரியவில்லை; நகரம் முழுதும் சாம்பலாயிற்று.',
        '0.11': '“என் அறிவு பிறழ்ந்ததால் அந்தக் காரியம் கெட்டிருந்தால், இன்று இங்கேயே உயிரை விடுவதே எனக்குச் சரியெனப் படுகிறது.',
        '0.12': '“இன்று நான் நெருப்பில் விழவா, அல்லது வடவைத் தீயில் விழவா, அல்லது கடல்வாழ் உயிர்களுக்கு இந்த உடலைக் கொடுக்கவா?',
        '0.13': '“காரியம் முழுவதையும் அழித்த நான் உயிரோடிருந்து வானர அரசனையோ அந்த இரு ஆண்சிங்கங்களையோ எப்படிக் காண முடியும்?',
        '0.14': '“மூவுலகிலும் புகழ்பெற்ற குரங்கு இயல்பின் நிலையற்ற தன்மையையே நான் சினக் குற்றத்தால் வெளிப்படுத்திவிட்டேன்.',
        '0.15': '“கட்டுப்பாடற்ற, நிலையற்ற இந்த ராஜஸ இயல்புக்கு ஐயோ; வல்லமை இருந்தும் ஆவேசத்தில் நான் சீதையைக் காக்கவில்லை.',
        '0.16': '“சீதை அழிந்தால் அவ்விருவரும் அழிவார்கள்; அவர்கள் அழிந்தால் சுக்ரீவன் உறவினருடன் அழிவான்.',
        '0.17': '“இந்தச் செய்தியைக் கேட்டு, சகோதரனிடம் அன்புடைய அறவோன் பரதன் சத்ருக்னனுடன் எப்படி உயிர் வாழ முடியும்?',
        '0.18': '“அறம் மிக்க இக்ஷ்வாகு குலம் அழிந்தால், மக்கள் அனைவரும் ஐயமின்றித் துயரத்தாலும் வேதனையாலும் வருந்துவார்கள்.',
        '0.19': '“ஆகவே நற்பேறற்றவனும், அறம் பொருள் சேர்க்கையை இழந்தவனும், சினக் குற்றத்தால் சூழப்பட்ட மனமுடையவனுமான நான் தெளிவாக உலகை அழிப்பவனே.”',
        '0.20': 'அவன் இவ்வாறு எண்ணிக்கொண்டிருந்தபோது, முன்பும் கண்டிருந்த நற்சகுனங்கள் தோன்றின; அவற்றை அவன் மீண்டும் நேரடியாகச் சிந்தித்தான்.',
        '0.21': '“அல்லது எல்லா உறுப்புகளிலும் அழகிய மங்கலமானவள் தன் ஒளியாலேயே காக்கப்பட்டிருப்பாள், அழிய மாட்டாள்; நெருப்பு நெருப்பின் மேல் செயல்படாது.',
        '0.22': '“அந்த அறவோனும் அளவற்ற ஒளியுடையவனுமானவனின் மனைவியை, தன் ஒழுக்கத்தாலேயே காக்கப்பட்ட அவளை நெருப்பு தொட முடியாது.',
        '0.23': '“எரிப்பதே தொழிலான இந்த நெருப்பு என்னை எரிக்காதது ராமனின் ஆற்றலாலும் வைதேஹியின் புண்ணியத்தாலுமே என்பது உறுதி.',
        '0.24': '“பரதன் முதலிய மூன்று சகோதரர்களுக்கும் தெய்வமானவளும், ராமனின் மனத்துக்கு இனியவளுமான அவள் எப்படி அழிவாள்?',
        '0.25': '“எங்கும் எரிக்க வல்ல அழிவற்ற இந்த நெருப்பு என் வாலையே எரிக்காதபோது உத்தமியை எப்படி எரிக்கும்?”',
        '0.26': 'அப்போது வியப்புற்ற ஹனுமான் கடலின் நடுவில் ஹிரண்யநாப மலை (மைனாகம்) தோன்றியதை மீண்டும் நினைத்தான்.',
        '0.27': '“தவத்தாலும் சத்தியச் சொல்லாலும் கணவனிடம் கொண்ட ஒருமைப் பற்றாலும் அவளே நெருப்பை எரித்துவிடுவாள்; நெருப்பு அவளை எரிக்காது.”',
        '0.28': 'தேவியின் அறப்பற்றைப் பற்றி இவ்வாறு சிந்தித்தபோது, ஹனுமான் அங்கே மகாத்மாக்களான சாரணர்களின் சொற்களைக் கேட்டான்:',
        '0.29': '“ஆகா, அரக்கர்களின் இருப்பிடத்தில் கடுமையான பயங்கர நெருப்பை விட்டு, ஹனுமான் எத்தகைய அரிய செயலைச் செய்துள்ளான்!',
        '0.30': '“ஓடும் அரக்கப் பெண்கள், குழந்தைகள், முதியோரால் நிறைந்து, மக்களின் கூச்சலால் முழங்கும் இந்த நகரம் மலைக்குகைகள் வழியே அழுவது போல் இருக்கிறது.',
        '0.31': '“மாடங்கள், மதில்கள், தோரணங்களுடன் இந்த லங்கை நகரம் எரிந்தது, ஆனால் ஜானகி எரியவில்லை — இது நமக்கு அற்புதமான வியப்பு!”',
        '0.32': 'அமுதம் போன்ற அந்தச் சொல்லை ஹனுமான் கேட்டான்; அவனுடைய மனத்தில் அந்நேரத்துக்கு ஏற்ற மகிழ்ச்சி உண்டாயிற்று.',
        '0.33': 'பொருளைக் கண்ட சகுனங்களாலும், பெரும் காரணங்களாலும், முனிவர்களின் சொற்களாலும் ஹனுமானின் மனம் மகிழ்ந்தது.',
        '0.34': 'அப்போது விருப்பம் நிறைவேறிய கபி, இளவரசி காயமின்றி இருப்பதை அறிந்து, அவளை மீண்டும் ஒருமுறை நேரில் கண்டு திரும்பிச் செல்லத் தீர்மானித்தான்.',
        '0.35': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் ஐம்பத்தைந்தாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-56': {
      verses: {
        '0.0': 'பின்னர் சிம்சுபா மரத்தடியில் அமர்ந்திருந்த ஜானகியை வணங்கி அவன் கூறினான்: “நற்பேறாக உன்னை இங்கே காயமின்றிக் காண்கிறேன்.”',
        '0.1': 'அப்போது புறப்படவிருந்த ஹனுமானை மீண்டும் மீண்டும் நோக்கியவாறு, கணவன் மீதான அன்பால் நிறைந்த சீதை அவனிடம் கூறினாள்:',
        '0.2': '“மகனே, பாவமற்றவனே, உனக்குச் சரியெனப் பட்டால் இங்கே ஒரு நாள் தங்கு; ஏதேனும் மறைவான இடத்தில் ஓய்வெடுத்து நாளை போ.',
        '0.3': '“வானரனே, உன் அருகாமையால் நற்பேறு குறைந்த என் அளவற்ற துயரம் சிறிது நேரமாவது குறையக்கூடும்.',
        '0.4': '“வானரப் புலியே, நீ சென்றபின் மீண்டும் வரும்வரை என் உயிரின் மேலும் எனக்கு நம்பிக்கை இல்லை.',
        '0.5': '“வீரனே, துயரத்திலிருந்து பெருந்துயரத்துக்குச் சென்று, மனவேதனையாலும் சோகத்தாலும் வாடிய என்னை, உன்னைக் காணாமை மேலும் பிளந்துவிடும்.',
        '0.6': '“வீரனே, இந்த ஐயம் என் முன் நிற்பது போல் இருக்கிறது: பெரும் துணைவர்களான வானரர் கரடிகள் இருந்தும், வலிமைமிக்க சுக்ரீவன்',
        '0.7': '“கடக்க முடியாத கடலை எப்படிக் கடப்பான்? அந்த வானரர் கரடிப் படைகளும், அல்லது மனிதரில் சிறந்தவனின் அந்த இரு மைந்தர்களும் எப்படிக் கடப்பார்கள்?',
        '0.8': '“கடலைத் தாண்டும் ஆற்றல் மூன்று உயிர்களுக்கு மட்டுமே உண்டு — வினதையின் மகன் கருடனுக்கு, உனக்கு, அல்லது காற்றுக்கு.',
        '0.9': '“ஆகவே இந்தக் கடினமான சிக்கல் எழுந்திருக்கும்போது நீ என்ன தீர்வைக் காண்கிறாய்? நீயே காரியத்தில் வல்லவன் அல்லவா.',
        '0.10': '“பகைவீரர்களைக் கொல்பவனே, இந்தக் காரியத்தைச் சாதிக்க நீ ஒருவனே போதும் என்பது உண்மை; அதன் பலன் உனக்குப் புகழ் தரும்.',
        '0.11': '“ஆனால் பகைப்படையை நசுக்கும் காகுத்ஸ்தன் தன் படைகளால் லங்கையை நிரப்பி என்னை அழைத்துச் சென்றால், அதுவே அவனுக்குத் தகுந்ததாகும்.',
        '0.12': '“ஆகவே போர்வீரனான அந்த மகாத்மாவின் வீரத்துக்கு ஏற்றதாக அமையும்படி நீ ஏற்பாடு செய்.”',
        '0.13': 'பொருள்நிறைந்த, பணிவான, காரணம் பொருந்திய அந்தச் சொற்களைக் கேட்டு வீர ஹனுமான் மறுமொழி கூறினான்:',
        '0.14': '“தேவி, வானரர் கரடிப் படைகளின் தலைவனும், தாவுவோரில் சிறந்தவனும், வலிமை மிக்கவனுமான சுக்ரீவன் உனக்காக உறுதியான முடிவு எடுத்துள்ளான்.',
        '0.15': '“வைதேஹி, கோடிக்கணக்கான ஆயிரம் வானரர்கள் சூழ, வானர அரசன் சுக்ரீவன் விரைவில் வருவான்.',
        '0.16': '“வீரர்களும் மனிதரில் சிறந்தவர்களுமான ராம லக்ஷ்மணர் இருவரும் சேர்ந்து லங்கை நகருக்கு வந்து அம்புகளால் அதைத் தகர்ப்பார்கள்.',
        '0.17': '“அழகியே, அரக்கனை அவன் கூட்டத்துடன் கொன்று, ரகுநந்தனன் விரைவில் உன்னை அழைத்துக்கொண்டு தன் நகருக்குச் செல்வான்.',
        '0.18': '“ஆறுதல் கொள், உனக்கு நலம் உண்டாகட்டும்; தக்க காலத்தை எதிர்பார். விரைவில் போரில் ராமனால் கொல்லப்பட்ட ராவணனைக் காண்பாய்.',
        '0.19': '“மகன்கள், அமைச்சர்கள், உறவினர்களுடன் அரக்கர் அரசன் கொல்லப்பட்டதும், ரோகிணி சந்திரனுடன் சேர்வது போல் நீ ராமனுடன் சேர்வாய்.',
        '0.20': '“சிறந்த வானரர் கரடிகளுடன் காகுத்ஸ்தன் விரைவில் வருவான்; போரில் பகைவர்களை வென்று உன் துயரத்தை நீக்குவான்.”',
        '0.21': 'இவ்வாறு வைதேஹியைத் தேற்றி, வாயுபுத்திரன் ஹனுமான் புறப்பட முடிவுசெய்து வைதேஹியை வணங்கினான்.',
        '0.22': 'முக்கிய அரக்கர்களைக் கொன்று, தன் பெயரை அறிவித்து, வைதேஹியைத் தேற்றி, தன் உயர்ந்த வலிமையைக் காட்டி,',
        '0.23': 'நகரைக் கலக்கி, ராவணனை ஏமாற்றி, பயங்கர வலிமையைக் காட்டி, வைதேஹியை வணங்கி,',
        '0.24': 'மீண்டும் கடலின் நடுவே திரும்பிச் செல்ல அவன் மனம் கொண்டான். அப்போது தலைவனைக் காண ஆர்வமுடைய அந்த வானரப் புலி,',
        '0.25': 'பகைவரை நசுக்குபவனான அவன், உயர்ந்த பத்மக மரங்கள் நிறைந்த கருநீல வனவரிசைகளுடைய சிறந்த மலையான அரிஷ்டத்தின் மேல் ஏறினான்,',
        '0.26': 'சிகரங்களுக்கு இடையே தொங்கும் மேகங்களால் மேலாடை அணிந்தது போலவும், சூரியனின் நற்கதிர்களால் அன்புடன் எழுப்பப்படுவது போலவும் இருந்த;',
        '0.27': 'ஒளிரும் தாதுக்களாகிய கண்களால் கண் திறப்பது போலவும், நீர்ப்பெருக்குகளின் ஆழ்ந்த ஒலியால் ஓதுவது போலவும் இருந்த;',
        '0.28': 'பல நீரூற்றுகளின் ஒலியால் தெளிவாகப் பாடுவது போலவும், உயர்ந்த தேவதாரு மரங்களால் கைகளை உயர்த்தி நிற்பது போலவும் இருந்த;',
        '0.29': 'அருவிகளின் முழக்கத்தால் எல்லாப் பக்கமும் கூவுவது போலவும், அசையும் கருநிறக் கூதிர்காடுகளால் நடுங்குவது போலவும் இருந்த;',
        '0.30': 'காற்றில் அசையும் உள்ளீடற்ற மூங்கில்களால் சீழ்க்கை அடிப்பது போலவும், கொடிய பெரும் பாம்புகளால் சினத்துடன் சீறுவது போலவும் இருந்த;',
        '0.31': 'பனியால் ஆழமான குகைகளால் தியானிப்பது போலவும், மேகம் போன்ற அடிவாரங்களால் எல்லாப் பக்கமும் அடியெடுத்து வைப்பது போலவும் இருந்த;',
        '0.32': 'மேகமாலை சூடிய சிகரங்களால் வானில் கொட்டாவி விடுவது போலவும், பல முகடுகள் நிறைந்தும் பல குகைகளால் அழகுபெற்றும் இருந்த;',
        '0.33': 'பல சால, பனை, கர்ணிகார, மூங்கில் மரங்களால் சூழப்பட்ட, பரந்த பூத்த கொடிப்பந்தல்களால் அலங்கரிக்கப்பட்ட;',
        '0.34': 'பலவகை விலங்குக் கூட்டங்கள் நிறைந்த, வழியும் தாதுக்களால் அலங்கரிக்கப்பட்ட, பல நீரூற்றுகள் உடைய, பாறைக் குவியல்கள் நெருங்கிய;',
        '0.35': 'மகரிஷிகள், யக்ஷர், கந்தர்வர், கின்னரர், நாகர்கள் வாழும், கொடிகளும் மரங்களும் அடர்ந்த, சிங்கங்கள் தங்கும் குகைகளுடைய,',
        '0.36': 'புலி முதலிய விலங்குகள் நிறைந்த, சுவையான கிழங்கு கனிகள் தரும் மரங்களுடைய அந்த மலையின் மேல் வானர சிரேஷ்டனான வாயுபுத்திரன் ஏறினான்,',
        '0.37': 'ராமனை விரைவில் காணும் மகிழ்ச்சியால் தூண்டப்பட்டு. அழகிய மலைச்சரிவுகளில் அவனுடைய உள்ளங்கால்களால் மிதிக்கப்பட்ட',
        '0.38': 'பாறைகள் ஓசையுடன் உடைந்து தூளாயின. அந்த மலையரசன் மேல் ஏறி அந்த மகாகபி உடலைப் பெருக்கினான்,',
        '0.39': 'உப்புக்கடலின் தென்கரையிலிருந்து வடகரையை அடைய விரும்பி. பின் மலையில் ஏறிய வீர வாயுபுத்திரன்',
        '0.40': 'பயங்கரப் பாம்புகள் வாழும் கொடிய கடலைக் கண்டான். காற்றைப் போலவே காற்றின் மகன் வானை அடைந்தான்,',
        '0.41': 'அந்த வானரப் புலி தெற்கிலிருந்து வடதிசை நோக்கிப் புறப்பட்டான். அப்போது அந்தக் கபியால் அழுத்தப்பட்ட அந்தச் சிறந்த மலை',
        '0.42': 'பலவகை உயிர்கள் வாயிலாக அலறி, நடுங்கும் சிகரங்களுடனும் விழும் மரங்களுடனும் பூமிக்குள் அமிழ்ந்தது.',
        '0.43': 'அவனுடைய தொடைகளின் வேகத்தால் கலக்கப்பட்ட பூத்த மரங்கள், இந்திரனின் வஜ்ராயுதத்தால் தாக்கப்பட்டது போல் முறிந்து தரையில் விழுந்தன.',
        '0.44': 'குகைகளின் உள்ளே வாழ்ந்த, நசுக்கப்பட்ட வலிமைமிக்க சிங்கங்களின் பயங்கர முழக்கம் வானைப் பிளப்பது போல் கேட்டது.',
        '0.45': 'அஞ்சிய, கலைந்த ஆடைகளும் சிதறிய அணிகலன்களும் உடைய வித்யாதரப் பெண்கள் திடீரென மலையிலிருந்து மேலே பறந்தனர்.',
        '0.46': 'மிகப் பெரிய, வலிமையான, ஒளிரும் நாக்குகளும் கொடிய நஞ்சும் உடைய பெரும் பாம்புகள் தலைகளும் கழுத்துகளும் நசுங்கித் துடித்தன.',
        '0.47': 'கின்னரர், நாகர், கந்தர்வர், யக்ஷர், வித்யாதரர் ஆகியோர் அழுத்தப்பட்ட அந்த மலையை விட்டு வானை அடைந்தனர்.',
        '0.48': 'அந்த வலியவனால் அழுத்தப்பட்ட அந்த அழகிய மலை மரங்களுடனும் உயர்ந்த சிகரங்களுடனும் பாதாளத்தில் நுழைந்தது.',
        '0.49': 'பத்து யோஜனை அகலமும் முப்பது யோஜனை உயரமும் உடைய அந்த மலை தரையோடு சமமானது.',
        '0.50': 'அலைகள் மோதும் கரையுடைய பயங்கர உப்புக்கடலை விளையாட்டாகத் தாண்ட விரும்பி, அந்தக் கபி வானுக்குத் தாவினான்.',
        '0.51': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் ஐம்பத்தாறாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
  },
};
